d=gethui
end
local function cloneSafe(e)
if e==nil then return nil end
if type(cloneref)=="function"then
local f,g=pcall(cloneref,e)
if f and g~=nil then return g end
end
return e
end
a.gethui=function()
if type(d)=="function"then
local e,f=pcall(d)
if e and f~=nil then return cloneSafe(f)or f end
end
local e=c.LocalPlayer
if e then
local f=e:FindFirstChildOfClass"PlayerGui"
if f then return cloneSafe(f)or f end
end
return cloneSafe(b)or b
end
end

local function Fail(a)
warn("[reversalloader]: "..a)

local b=_G.Players.LocalPlayer
if b then
b:Kick("[reversalloader]\n"..a)
end

error(a,0)
end

local function HttpGet(a)
local b={
{
name="game:HttpGet",
func=function()
return game:HttpGet(a)
end
},
{
name="syn.request",
func=function()
if not(syn and syn.request)then
error"syn.request does not exist"
end

local b=syn.request{Url=a,Method="GET"}
if not b then error"nil response"end
if b.StatusCode and b.StatusCode~=200 then
error("HTTP "..tostring(b.StatusCode))
end

return b.Body
end
},
{
name="http_request",
func=function()
if not http_request then
error"http_request does not exist"
end

local b=http_request{Url=a,Method="GET"}
if not b then error"nil response"end
if b.StatusCode and b.StatusCode~=200 then
error("HTTP "..tostring(b.StatusCode))
end

return b.Body
end
},
{
name="request",
func=function()
if not request then
error"request does not exist"
end

local b=request{Url=a,Method="GET"}
if not b then error"nil response"end
if b.StatusCode and b.StatusCode~=200 then
error("HTTP "..tostring(b.StatusCode))
end

return b.Body
end
}
}

local c={}

for d,e in ipairs(b)do
local f,g=pcall(e.func)

if f and type(g)=="string"and#g>0 then
return g
end

table.insert(c,e.name..": "..tostring(g))
end

Fail("http requests failed, error (report this to umbrella):\n"..table.concat(c,"\n"))
end

