local j="soundlib"

if not isfolder(j)then
makefolder(j)
end

local k={}

function _G._loadLibSound(l)
if k[l]and k[l].Parent then
return k[l]
end

local m=_G._soundLib[l]
if not m then
return nil
end

local n=m:match"%.([%a%d]+)$"or"wav"
local o=j.."/"..l.."."..n

if not isfile(o)then
local p,q=pcall(game.HttpGet,game,m)

if not p or not q then
return nil
end

writefile(o,q)
end

local p=getSoundFolder()

local q=Instance.new"Sound"
q.Name=l
q.SoundId=getcustomasset(o)
q.Volume=0.5
q.Parent=p

k[l]=q

return q
end

function _G._playLibSound(l,m)
local n=_G._loadLibSound(l)

if not n then
return
end

n.Volume=m or 0.5
n:Play()
end

function _G._playLibSoundMulti(l,m)
if not l or#l==0 then
return
end

_G._playLibSound(l[math.random(1,#l)],m)
end
end
do
_G._aura_select=_G._aura_select or"none"
_G._aura_color=_G._aura_color or Color3.fromRGB(255,255,255)
local i={starlight=
"rbxassetid://134645216613107",heavenly="rbxassetid://139300897520961",ribbon=
"rbxassetid://132069507632161",sakura="rbxassetid://81755778619404",angel=
"rbxassetid://97658130917593",wind="rbxassetid://80694081850877",flow=
"rbxassetid://119913533725648",star="rbxassetid://73754563740680",
}
local j={}
local k=game:GetService"Players".LocalPlayer

function _G._aura_clear()
for l,m in ipairs(j)do
pcall(function()if m and m.Parent then m:Destroy()end end)
end
j={}
end

function _G._aura_apply(l,m)
_G._aura_clear()
l=l or _G._aura_select
m=m or _G._aura_color
if not l or l=="none"then return end
local n=i[l];if not n then return end
local o=k.Character;if not o then return end
local p=ColorSequence.new(m)
local q,r=pcall(function()return game:GetObjects(n)end)
if not q or not r or#r==0 then warn("[aura] failed: "..tostring(n));return end
local s=r[1]
for t,u in ipairs(s:GetChildren())do
local v=o:FindFirstChild(u.Name)
if v then
for w,x in ipairs(u:GetChildren())do
local y=x:Clone()
if y:IsA"ParticleEmitter"then y.Color=p
elseif y:IsA"Beam"or y:IsA"Trail"then y.Color=p;y.Enabled=true
elseif y:IsA"PointLight"then y.Color=m end
y.Name="\0\0";y.Parent=v
table.insert(j,y)
end
end
end
pcall(function()s:Destroy()end)
end

k.CharacterAdded:Connect(function()
task.wait(1)
if _G._aura_select and _G._aura_select~="none"then
_G._aura_apply(_G._aura_select,_G._aura_color)
end
end)
end

