local function _getPlayerState()
local m=LocalPlayer and LocalPlayer.Character
if not m then return"offline"end
local n=m:FindFirstChildOfClass"Humanoid"
if not n or n.Health<=0 then return"dead"end
local o=m:FindFirstChild"HumanoidRootPart"
local p=o and o.AssemblyLinearVelocity or Vector3.zero
local q=Vector2.new(p.X,p.Z).Magnitude
if n.FloorMaterial==Enum.Material.Air then
return p.Y>1 and"jumping"or(p.Y<-2 and"falling"or"inair")
elseif n.Sit then return"sitting"
elseif q>0.5 then return"walking"
else return"idle"end
end
_G._getPlayerState=_getPlayerState

function setAutoStatus(m)
autoShootStatus=m

local n=""
local o=LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass"Tool"
if o then
local p=o:GetAttribute"CurrentAmmo"or o:GetAttribute"Local_CurrentAmmo"or 0
n=" "..tostring(p)
end
local p=currentTarget and(currentTarget.Name or"")or""
local q=currentTarget and(currentTarget.DisplayName or currentTarget.Name or"")or""
local r=_getPlayerState()

if statusLabel then
local s=m

local function _applyPlaceholders(t)
t=t:gsub("{TARGET}",p)
t=t:gsub("{DISPLAYNAME}",q)
t=t:gsub("{AMMO}",n:gsub("^%s+",""))
t=t:gsub("{STATE}",r or"")
return t
end

if m=="idle"then
s=_applyPlaceholders(_G.status_text_idle or"aim: idle")
elseif m=="shooting"then
s=_applyPlaceholders(_G.status_text_shooting or"aim: shooting")
elseif m=="killed"then
local t=_G.status_text_killing or"aim: killed {TARGET}"

if not t:find"{TARGET}"and p~=""then
t=t.." "..p
end
s=_applyPlaceholders(t)
elseif m=="stopping"then
s=_applyPlaceholders(_G.status_text_stopping or"aim: stopping")
end

statusLabel.Text=s
statusLabel.Font=_G.status_font or Enum.Font.GothamBold
statusLabel.TextSize=_G.status_textsize or 13
local t=cfg.statuscolor or _G.status_label_color or Color3.fromRGB(255,255,255)
statusLabel.TextColor3=(m=="killed"or m=="killing")
and(_G.status_killing_color or Color3.fromRGB(220,50,50))
or t

local u=_G.status_follow_mode or"default"
if u=="mouse"then
local v=UserInputService:GetMouseLocation()
statusLabel.Position=UDim2.new(0,v.X+(_G.status_pos_ox or 10),0,v.Y+(_G.status_pos_oy or 10))
elseif u=="tool"then
local v=LocalPlayer.Character
local w=v and v:FindFirstChildOfClass"Tool"
local x=w and w:FindFirstChild"Handle"
if x then
local y,z=workspace.CurrentCamera:WorldToViewportPoint(x.Position)
if z then
local A=y.X+(_G.status_pos_ox or 0)
local B=y.Y+(_G.status_pos_oy or 20)
if _G.status_tool_lerp then
_G._statusToolPos=_G._statusToolPos or Vector2.new(A,B)
_G._statusToolPos=_G._statusToolPos+(Vector2.new(A,B)-_G._statusToolPos)*0.15
A,B=_G._statusToolPos.X,_G._statusToolPos.Y
end
statusLabel.Position=UDim2.new(0,A,0,B)
else
_G._statusToolPos=nil
statusLabel.Position=UDim2.new(_G.status_pos_x or 0.5,_G.status_pos_ox or 0,_G.status_pos_y or 0.5,_G.status_pos_oy or-5)
end
else
_G._statusToolPos=nil
statusLabel.Position=UDim2.new(_G.status_pos_x or 0.5,_G.status_pos_ox or 0,_G.status_pos_y or 0.5,_G.status_pos_oy or-5)
end
elseif u=="ragefov"then
local v=currentTarget
if v and v.Character then
local w=v.Character:FindFirstChild"Head"or v.Character:FindFirstChild"HumanoidRootPart"
if w then
local x,y=workspace.CurrentCamera:WorldToViewportPoint(w.Position)
if y then
local z=x.X+(_G.status_pos_ox or 0)
local A=x.Y+(_G.status_pos_oy or 20)
if _G.status_tool_lerp then
_G._statusRFPos=_G._statusRFPos or Vector2.new(z,A)
_G._statusRFPos=_G._statusRFPos+(Vector2.new(z,A)-_G._statusRFPos)*0.12
z,A=_G._statusRFPos.X,_G._statusRFPos.Y
end
statusLabel.Position=UDim2.new(0,z,0,A)
end
end
else
statusLabel.Position=UDim2.new(_G.status_pos_x or 0.5,_G.status_pos_ox or 0,_G.status_pos_y or 0.5,_G.status_pos_oy or-5)
end
else

statusLabel.Position=UDim2.new(_G.status_pos_x or 0.5,_G.status_pos_ox or 0,_G.status_pos_y or 0.5,_G.status_pos_oy or-5)
end
end

if _G._statusLabel2 then
if m=="killed"and currentTarget then
_G._statusLabel2.Text=currentTarget.Name or""
_G._statusLabel2.TextColor3=_G.status_target_color or Color3.fromRGB(255,255,255)
_G._statusLabel2.Visible=true
else
_G._statusLabel2.Visible=false
end
end

local s=_G._psLabel
if s then
local t=_G.ps_label_enabled and(statusLabel and statusLabel.Visible)
s.Visible=t and true or false
if t then
local u=_G.ps_label_text or'{STATE}'
u=u:gsub('{STATE}',r or'idle')
:gsub('{TARGET}',p)
:gsub('{AMMO}',n:gsub('^%s+',''))
s.Text=u
s.TextColor3=_G.ps_label_color or Color3.fromRGB(180,220,255)
s.TextSize=_G.ps_label_textsize or 11

local v=statusLabel.AbsolutePosition
local w=statusLabel.AbsoluteSize
s.Position=UDim2.new(0,v.X+w.X/2,0,v.Y+w.Y+(_G.ps_label_offset_y or 2))

local x=_G._psGrad or s:FindFirstChildOfClass'UIGradient'
if x then
x.Enabled=_G.ps_label_grad and true or false
if _G.ps_label_grad then
x.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,_G.ps_label_grad_c1 or Color3.fromRGB(100,200,255)),
ColorSequenceKeypoint.new(1,_G.ps_label_grad_c2 or Color3.fromRGB(255,100,200))
}
end
end
end
end
end

