fovCircle=setmetatable({},{
__newindex=function(m,n,o)
rawset(m,'_'..n,o)
local p=_G._fovSGFrame
if not p then return end
if n=='Visible'then
p.Visible=o
elseif n=='Radius'then
p.Size=UDim2.new(0,o*2,0,o*2)
elseif n=='Color'then
cfg.fovcolor=o
if _G._fovSGGradient then
_G._fovSGGradient.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,o),
ColorSequenceKeypoint.new(0.5,cfg.fovcolor2 or o),
ColorSequenceKeypoint.new(1,cfg.fovcolor3 or o),
}
end
elseif n=='Transparency'then
p.BackgroundTransparency=o

if not rawget(m,'_Filled')then
p.BackgroundTransparency=1
end
elseif n=='Position'then
p.Position=UDim2.new(0,o.X,0,o.Y)
elseif n=='Filled'then
if o then
p.BackgroundTransparency=cfg.fovtransparency
if _G._fovSGStroke then _G._fovSGStroke.Enabled=false end

else
p.BackgroundTransparency=1
if _G._fovSGStroke then
_G._fovSGStroke.Enabled=true
_G._fovSGStroke.Color=_G.fov_outline_color or cfg.fovcolor
_G._fovSGStroke.Transparency=_G.fov_outline_trans or 0
_G._fovSGStroke.Thickness=_G.fov_outline_thickness or cfg.fovthickness or 1.5
end
end
end
end,
__index=function(m,n)return rawget(m,'_'..n)end,
})
