function isC4Part(m)
if not m or not m:IsA"BasePart"then return false end
local n=m.Name:lower()
local o=m.Parent and m.Parent.Name:lower()or""
return n=="explosive"or n=="c4"or n=="clientc4"or
o:find"c4"or n:find"c4"
end

function onDescendantAdded(m)
if isC4Part(m)then trackedC4s[m]=true end
end

function onDescendantRemoving(m)
trackedC4s[m]=nil
if c4espCache[m]then
c4espCache[m]:Destroy()
c4espCache[m]=nil
end
end

for m,n in ipairs(workspace:GetDescendants())do
if isC4Part(n)then trackedC4s[n]=true end
end
workspace.DescendantAdded:Connect(onDescendantAdded)
workspace.DescendantRemoving:Connect(onDescendantRemoving)

function updateC4Esp()
if not cfg.c4esp or not visuals.container then
for m,n in pairs(c4espCache)do n.Parent=nil end
return
end

local m=LocalPlayer.Character
local n=m and m:FindFirstChild"HumanoidRootPart"

for o in pairs(trackedC4s)do
if o and o:IsDescendantOf(workspace)then
local p=0
if n then p=(o.Position-n.Position).Magnitude end

if p<=cfg.c4espmaxdist then
local q=makeC4Esp(o)
q.Adornee=o
q.Parent=visuals.container

if cfg.c4espshowdist and n then
local r=q:FindFirstChild"DistLabel"
if r then r.Text=math.floor(p).."m"end
end
else
local q=c4espCache[o]
if q then q.Parent=nil end
end
else
trackedC4s[o]=nil
if c4espCache[o]then
c4espCache[o]:Destroy()
c4espCache[o]=nil
end
end
end
end

