function getGlowColors(m)
if cfg.glowuseteamcolors and m then
local n=m.Team
if n==LocalPlayer.Team then
return cfg.glowteamcolor,cfg.glowteamtransparency,cfg.glowteamfill,cfg.glowteamfilltransparency
elseif n==guardsTeam then
return cfg.glowguardscolor,cfg.glowguardstransparency,cfg.glowguardsfill,cfg.glowguardsfilltransparency
elseif n==inmatesTeam then
return cfg.glowinmatescolor,cfg.glowinmatestransparency,cfg.glowinmatesfill,cfg.glowinmatesfilltransparency
elseif n==criminalsTeam then
return cfg.glowcriminalscolor,cfg.glowcriminalstransparency,cfg.glowcriminalsfill,cfg.glowcriminalsfilltransparency
end
end
return cfg.glowcolor,cfg.glowtransparency,cfg.glowfill,cfg.glowfilltransparency
end

