s.FillColor=q
s.FillTransparency=r
s.OutlineColor=o
s.OutlineTransparency=p
s.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
s.Parent=m

glowCache[m]={highlight=s,player=n}
end

function removeGlowESP(m)
if glowCache[m]then
if glowCache[m].highlight then
glowCache[m].highlight:Destroy()
end
glowCache[m]=nil
end
end

