function createPlayerTrail()

for m,n in ipairs(_G._trailObjects)do
if n and n.Parent then n:Destroy()end
end
_G._trailObjects={}
if _G.playerTrail then _G.playerTrail:Destroy();_G.playerTrail=nil end

