local n=_G.trail_limbs or{hrp=true}
local o=false

for p,q in pairs(_LIMB_PARTS)do
if n[p]then
local r=m:FindFirstChild(q)
if r and r:IsA"BasePart"then
local s=Instance.new"Attachment"
s.Position=Vector3.new(-0.5,0,0);s.Parent=r
local t=Instance.new"Attachment"
