u.WidthScale=NumberSequence.new(1);u.MinLength=0
u.Attachment0=s;u.Attachment1=t
u.Parent=r
table.insert(_G._trailObjects,u)
o=true
end
end
end

if o and#_G._trailObjects>0 then
_G.playerTrail=_G._trailObjects[1]
end
