_G.cs2bhop_enabled=false
_G.cs2bhop_autojump=false
_G.cs2bhop_startspeed=16
_G.cs2bhop_accelrate=8
_G._cs2bhop_conn=nil
local m=game:GetService"UserInputService"

local function stopCS2Bhop()
if _G._cs2bhop_conn then _G._cs2bhop_conn:Disconnect();_G._cs2bhop_conn=nil end

local n=LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass"Humanoid"
if n then

n.WalkSpeed=16
end
end

local function setupCS2Bhop(n)
stopCS2Bhop()
if not _G.cs2bhop_enabled then return end
local o=n and n:FindFirstChildOfClass"Humanoid"
local p=n and n:FindFirstChild"HumanoidRootPart"
if not o or not p then return end

local q=_G.cs2bhop_startspeed
local r=false
local s=0
local t=16

_G._cs2bhop_conn=RunService.Heartbeat:Connect(function(u)
if not _G.cs2bhop_enabled then stopCS2Bhop();return end
if not o or not o.Parent then stopCS2Bhop();return end

local v=o.FloorMaterial==Enum.Material.Air
local w=o.MoveDirection.Magnitude>0.05
local x=_G.cs2bhop_autojump or m:IsKeyDown(Enum.KeyCode.Space)

local y=(getgenv().speedBypass and getgenv().speedBypass.enabled)
and getgenv().speedBypass.speed or _G.cs2bhop_startspeed

if not w then

s=s+1
if s>10 then
q=math.max(q-u*30,t)
end

return
end
s=0

if not v then

q=math.min(q+(_G.cs2bhop_accelrate*u),y)

o.WalkSpeed=q

if x then
if r then

o:ChangeState(Enum.HumanoidStateType.Jumping)
elseif _G.cs2bhop_autojump then
o:ChangeState(Enum.HumanoidStateType.Jumping)
end
end
else

o.WalkSpeed=q
end
r=v
end)
end

function setupBunnyHop()
if _G.bhopConnection then
_G.bhopConnection:Disconnect()
_G.bhopConnection=nil
end
if _G._cs2bhop_conn then stopCS2Bhop()end

