setupCS2Bhop(LocalPlayer.Character)
return
end

if not cfg.bunnyhop then return end

local n=LocalPlayer.Character
if not n then return end

local o=n:FindFirstChildOfClass"Humanoid"
if not o then return end

_G.bhopConnection=RunService.Heartbeat:Connect(function()
if o.FloorMaterial~=Enum.Material.Air and o.MoveDirection.Magnitude>0 then
o:ChangeState(Enum.HumanoidStateType.Jumping)
end
end)
end

