function setupJumpCircle(n)

if jumpCircleConnections[n]then
for o,p in ipairs(jumpCircleConnections[n])do
p:Disconnect()
end
jumpCircleConnections[n]=nil
end

if not cfg.jumpcircle then return end

local o=n:FindFirstChild"Humanoid"
local p=n:FindFirstChild"HumanoidRootPart"
if not o or not p then return end

local q
local r={}

local s=RunService.Heartbeat:Connect(function()
if o.FloorMaterial~=Enum.Material.Air then
q=p.Position-Vector3.new(0,o.HipHeight+1,0)
end
end)
table.insert(r,s)

local t=o.StateChanged:Connect(function(t,u)
if u~=Enum.HumanoidStateType.Jumping then return end
if not q or not cfg.jumpcircle then return end

local v=Instance.new"Part"
v.Anchored=true
v.CanCollide=false
v.Transparency=1
v.Material=Enum.Material.SmoothPlastic
v.Size=Vector3.new(0.05,0.05,0.05)
v.CFrame=CFrame.new(q+Vector3.new(0,0.05,0))
v.Parent=workspace

local w=Instance.new"Decal"
w.Texture=cfg.jumpcircledecal
w.Face=Enum.NormalId.Top
w.Color3=cfg.jumpcirclecolor or Color3.fromRGB(255,255,255)
w.Transparency=0
w.Parent=v

TweenService:Create(
v,
TweenInfo.new(cfg.jumpcirclegrowtime,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),
{Size=Vector3.new(cfg.jumpcirclesize,0.05,cfg.jumpcirclesize)}
):Play()

TweenService:Create(
w,
TweenInfo.new(cfg.jumpcirclefadetime,Enum.EasingStyle.Linear),
{Transparency=1}
):Play()

task.delay(cfg.jumpcirclefadetime,function()
v:Destroy()
end)
end)
table.insert(r,t)

local u=n.AncestryChanged:Connect(function()
if not n:IsDescendantOf(workspace)then
if jumpCircleConnections[n]then
for u,v in ipairs(jumpCircleConnections[n])do
v:Disconnect()
end
jumpCircleConnections[n]=nil
end
end
end)
table.insert(r,u)

jumpCircleConnections[n]=r
end

if LocalPlayer.Character then
setupJumpCircle(LocalPlayer.Character)
end
