PositionHistory={}
PositionHistory=PositionHistory
BacktrackClone=nil
BacktrackClone=BacktrackClone

function getPing()
local n=LocalPlayer:GetNetworkPing()*1000
return math.max(n,20)
end

function getRainbowColor()
local n=(tick()*0.5)%1
return Color3.fromHSV(n,1,1)
end

function getBacktrackColor()
return cfg.backtrackrainbow and getRainbowColor()or cfg.backtrackcolor
end

function createBacktrackClone(n,o)
local p=Instance.new"Model"
p.Name="BacktrackClone"

for q,r in ipairs(n:GetChildren())do
if r:IsA"BasePart"and r.Name~="HumanoidRootPart"then
local s=Instance.new"Part"
s.Size=r.Size
s.CFrame=o*n.HumanoidRootPart.CFrame:Inverse()*r.CFrame
s.Anchored=true
s.CanCollide=false
s.Material=Enum.Material.Plastic
s.Color=getBacktrackColor()
s.Transparency=cfg.backtracktransparency
s.Name=r.Name
s.CastShadow=false
s.Parent=p

local t=r:FindFirstChildOfClass"SpecialMesh"
if t then
t:Clone().Parent=s
end
end
end

if cfg.backtrackskeleton then
local q={
{"Head","UpperTorso"},{"UpperTorso","LowerTorso"},
{"UpperTorso","LeftUpperArm"},{"UpperTorso","RightUpperArm"},
{"LeftUpperArm","LeftLowerArm"},{"RightUpperArm","RightLowerArm"},
{"LeftLowerArm","LeftHand"},{"RightLowerArm","RightHand"},
{"LowerTorso","LeftUpperLeg"},{"LowerTorso","RightUpperLeg"},
{"LeftUpperLeg","LeftLowerLeg"},{"RightUpperLeg","RightLowerLeg"},
{"LeftLowerLeg","LeftFoot"},{"RightLowerLeg","RightFoot"},
}

for r,s in ipairs(q)do
local t=p:FindFirstChild(s[1])
local u=p:FindFirstChild(s[2])

if t and u then
local v=(t.Position-u.Position).Magnitude
local w=Instance.new"Part"
w.Size=Vector3.new(0.1,v,0.1)
w.CFrame=CFrame.new(t.Position,u.Position)*CFrame.new(0,-v/2,0)
w.Anchored=true
w.CanCollide=false
w.Material=Enum.Material.Plastic
w.Color=getBacktrackColor()
w.Transparency=cfg.backtracktransparency+0.2
w.CastShadow=false
w.Parent=p
end
end
end

return p
end

function updateBacktrackClone()
if not cfg.backtrack then
if BacktrackClone then
BacktrackClone:Destroy()
BacktrackClone=nil
end
return
end

local n=LocalPlayer.Character
if not n then return end

local o=n:FindFirstChild"HumanoidRootPart"
if not o then return end

local p=getPing()
local q=(p*cfg.backtrackping)/1000
local r=tick()-q

local s
local t=math.huge

for u,v in ipairs(PositionHistory)do
local w=math.abs(v.Time-r)
if w<t then
t=w
s=v
end
end

if s then
if BacktrackClone then
BacktrackClone:Destroy()
end

BacktrackClone=createBacktrackClone(n,s.CFrame)
BacktrackClone.Parent=workspace

if cfg.backtrackrainbow then
for u,v in ipairs(BacktrackClone:GetDescendants())do
if v:IsA"BasePart"then
v.Color=getRainbowColor()
end
end
end
end
end

function recordPosition()
local n=LocalPlayer.Character
if not n then return end

local o=n:FindFirstChild"HumanoidRootPart"
if not o then return end

table.insert(PositionHistory,{
Time=tick(),
CFrame=o.CFrame
})

local p=1
while#PositionHistory>0 and(tick()-PositionHistory[1].Time)>p do
table.remove(PositionHistory,1)
end
end

LocalPlayer.CharacterAdded:Connect(function()
if BacktrackClone then
BacktrackClone:Destroy()
BacktrackClone=nil
end
PositionHistory={}

if sessionStats.currentStreak>0 then
sessionStats.deaths=sessionStats.deaths+1
sessionStats.currentStreak=0
