_G.originalSettings={
Brightness=Lighting.Brightness,
Ambient=Lighting.Ambient,
OutdoorAmbient=Lighting.OutdoorAmbient,
ClockTime=Lighting.ClockTime,
GlobalShadows=Lighting.GlobalShadows,
}
originalSettings=_G.originalSettings

function removeTextures()
if not cfg.fpsboost.notextures then return end

for n,o in ipairs(workspace:GetDescendants())do
if o:IsA"Decal"or o:IsA"Texture"then
o.Transparency=1
elseif o:IsA"BasePart"then
o.Material=Enum.Material.SmoothPlastic
end
end
end

function removeDecals()
if not cfg.fpsboost.nodecals then return end

for n,o in ipairs(workspace:GetDescendants())do
if o:IsA"Decal"or o:IsA"Texture"or o:IsA"SurfaceGui"then
o:Destroy()
end
end
end

function removeParticles()
if not cfg.fpsboost.noparticles then return end

for n,o in ipairs(workspace:GetDescendants())do
if o:IsA"ParticleEmitter"or o:IsA"Trail"or o:IsA"Sparkles"or
o:IsA"Fire"or o:IsA"Smoke"or o:IsA"Beam"then
o.Enabled=false
end
end
end

function removeSky()
if not cfg.fpsboost.nosky then
return
end

for n,o in ipairs(Lighting:GetChildren())do
if o:IsA"Sky"or o:IsA"Atmosphere"or o:IsA"Clouds"then
o:Destroy()
end
end
end

function applyLowQuality()
if not cfg.fpsboost.lowquality then return end

settings().Rendering.QualityLevel=Enum.QualityLevel.Level01

for n,o in ipairs(workspace:GetDescendants())do
if o:IsA"BasePart"then
o.CastShadow=false
o.Material=Enum.Material.SmoothPlastic
elseif o:IsA"Explosion"then
o.BlastPressure=1
o.BlastRadius=1
end
end
end

function removeShadows()
if not cfg.fpsboost.noshadows then
Lighting.GlobalShadows=originalSettings.GlobalShadows
return
end

Lighting.GlobalShadows=false

for n,o in ipairs(workspace:GetDescendants())do
if o:IsA"BasePart"then
o.CastShadow=false
end
end
end

function applyNightMode()
if not cfg.fpsboost.nightmode then
Lighting.Brightness=originalSettings.Brightness
Lighting.Ambient=originalSettings.Ambient
Lighting.OutdoorAmbient=originalSettings.OutdoorAmbient
Lighting.ClockTime=originalSettings.ClockTime
return
end

Lighting.Brightness=0
Lighting.Ambient=Color3.fromRGB(0,0,0)
Lighting.OutdoorAmbient=Color3.fromRGB(0,0,0)
Lighting.ClockTime=0
end

function applyAllOptimizations()
removeTextures()
removeDecals()
removeParticles()
removeSky()
applyLowQuality()
removeShadows()
applyNightMode()

safeNotify('fps boost applied!',3)
end

function resetOptimizations()
cfg.fpsboost.notextures=false
cfg.fpsboost.nodecals=false
cfg.fpsboost.noparticles=false
cfg.fpsboost.nosky=false
cfg.fpsboost.lowquality=false
cfg.fpsboost.noshadows=false
cfg.fpsboost.nightmode=false

Lighting.Brightness=originalSettings.Brightness
Lighting.Ambient=originalSettings.Ambient
Lighting.OutdoorAmbient=originalSettings.OutdoorAmbient
Lighting.ClockTime=originalSettings.ClockTime
Lighting.GlobalShadows=originalSettings.GlobalShadows

settings().Rendering.QualityLevel=Enum.QualityLevel.Automatic

safeNotify('optimizations reset. rejoin for full reset.',4)
end

