function updateArraylist(n)
if not arraylistModules or not arraylistLabels then return end
local o={}
for p,q in ipairs(arraylistModules)do
if q[2]()then table.insert(o,{name=q[1],idx=p})end
end
table.sort(o,function(p,q)return#p.name>#q.name end)

local p={}
for q,r in ipairs(o)do
p[r.idx]=q
end

local q=0

for r,s in ipairs(o)do
local t=arraylistLabels[s.idx]
local u=t.label
local v=arraylistModules[s.idx]
local w=(s.idx%3)*5
local x=170-w

if not t.active then
t.active=true;t.currentH=0
end
t.currentH=math.min(t.currentH+(n or 1.6666666666666665E-2)*120,ROW_H)

u.Size=UDim2.new(0,x,0,t.currentH)
u.Position=UDim2.new(1,-x-4,0,q+(ROW_H-t.currentH)*0.5)
u.Text=v[1]
u.Visible=true

if _G.al_rainbow then
local y=((tick()*0.3)+s.idx*0.07)%1
local z=Color3.fromHSV(y,0.7,1)
u.TextColor3=z
t.accent.BackgroundColor3=z
else
u.TextColor3=_G.al_textcolor
t.accent.BackgroundColor3=_G.al_accent
end
u.BackgroundColor3=_G.al_bgcolor
u.BackgroundTransparency=_G.al_bgalpha
u.TextSize=_G.al_textsize

q=q+t.currentH+2
end

for r,s in ipairs(arraylistLabels)do
if not p[r]and s.active then
s.currentH=math.max(s.currentH-(n or 1.6666666666666665E-2)*120,0)
if s.currentH<=0 then
s.active=false;s.label.Visible=false
else
s.label.Size=UDim2.new(s.label.Size.X.Scale,s.label.Size.X.Offset,0,s.currentH)
end
end
end
end

