function getPart(aa,ab)
if not aa then return nil end
local ac=aa:FindFirstChild(ab)
if ac then return ac end

local n=partMap[ab]
if n then
for o,p in ipairs(n)do
local q=aa:FindFirstChild(p)
if q then return q end
end
end
return aa:FindFirstChild"HumanoidRootPart"or aa:FindFirstChild"Head"
end

getTargetPart=function(aa)
if not aa then return nil end

if cfg.shieldbreaker then
local ab=aa:FindFirstChild"RiotShieldPart"
