local p=aa:FindFirstChild"HumanoidRootPart"

if o and p then
local q=(o.Position-p.Position).Unit
local r=p.CFrame.LookVector
local s=q:Dot(r)

if s>cfg.shieldfrontangle then
if cfg.shieldrandomhead and i:NextInteger(1,100)<=cfg.shieldheadchance then
return getPart(aa,"Head")
end
return ab
end
end
end
end
end

