return ac
end

function isDead(aa)
if not aa or not aa.Character then return true end
local ab=aa.Character:FindFirstChildOfClass"Humanoid"
return not ab or ab.Health<=0
end

function isStanding(aa)
if not aa or not aa.Character then return false end
local ab=aa.Character:FindFirstChild"HumanoidRootPart"
if not ab then return false end
local ac=ab.AssemblyLinearVelocity
return Vector2.new(ac.X,ac.Z).Magnitude<=cfg.stillthreshold
end

function hasForceField(aa)
if not aa or not aa.Character then return false end
return aa.Character:FindFirstChildOfClass"ForceField"~=nil
end

function isInVehicle(aa)
if not aa or not aa.Character then return false end
local ab=aa.Character:FindFirstChildOfClass"Humanoid"
if not ab then return false end
return ab.SeatPart~=nil
end

function wallBetween(aa,ab,ac)
local n=LocalPlayer.Character
if not n then return true end

local o={n}
if ac then table.insert(o,ac)end
wallParams.FilterDescendantsInstances=o

local p=ab-aa
local q=p.Magnitude
local r=p.Unit

local s=aa
local t=q

for u=1,10 do
local v=workspace:Raycast(s,r*t,wallParams)
if not v then return false end

if v.Instance then return true end

local w=(v.Position-s).Magnitude
t=t-w-0.01
if t<=0 then return false end

s=v.Position+r*0.01
end
return false
end

function quickCheck(aa)
if not aa or aa==LocalPlayer or not aa.Character then return false end

if _G._whitelist_players and _G._whitelist_players[aa.Name]then return false end
if not getTargetPart(aa.Character)then return false end
if cfg.deathcheck and isDead(aa)then return false end
if cfg.ffcheck and hasForceField(aa)then return false end
if cfg.vehiclecheck and isInVehicle(aa)then return false end
if cfg.teamcheck and aa.Team==LocalPlayer.Team then return false end

local ab=cfg.targetteams
local ac=aa.Team
local n=aa.Character
local o=n and n:GetAttribute"Hostile"
local p=n and n:GetAttribute"Trespassing"


local q=LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass"Tool"
local r=q and(q:GetAttribute"Projectile"=="Taser"or q.Name:lower():find"taser")
if cfg.taserbypasstrespass and r and p then
return true
end

if ac==guardsTeam then
if not ab.guards then return false end
elseif ac==inmatesTeam then

local s=ab.inmates or ab.hostile_inmates or ab.trespass_inmates
if not s then return false end
if not ab.inmates then

if ab.hostile_inmates and o then
elseif ab.trespass_inmates and p then
else return false end
end
elseif ac==criminalsTeam then
if not ab.criminals then return false end
end

if cfg.criminalsnoinnmates and LocalPlayer.Team==criminalsTeam and ac==inmatesTeam then return false end
if cfg.inmatesnocriminals and LocalPlayer.Team==inmatesTeam and ac==criminalsTeam then return false end

return true
end

function fullCheck(aa)
if not quickCheck(aa)then return false end

if cfg.wallcheck then
local ab=LocalPlayer.Character
local ac=ab and ab:FindFirstChild"Head"
local n=getTargetPart(aa.Character)
if ac and n then
if wallBetween(ac.Position,n.Position,aa.Character)then
return false
end
end
end
return true
end

function rollHit()
local aa=os.clock()
if aa-lastShotTime>shotCooldown then
lastShotTime=aa
local ab=cfg.hitchance
if ab>=100 then
lastShotResult=true
elseif ab<=0 then
lastShotResult=false
else
lastShotResult=i:NextInteger(1,100)<=ab
end
end
return lastShotResult
end

