local function _getPastPosition(ac)
local n=os.clock()
for o=#aa,1,-1 do
if n-aa[o].t>=ac then
return aa[o].pos
end
end
return aa[1]and aa[1].pos or nil
end

local function closetMissByMovement(ac,n)
if not cfg.miss_by_movement then return nil end
if i:NextInteger(1,100)>cfg.miss_by_movement_chance then return nil end
local o=(cfg.miss_by_movement_history or 8)/60
local p=_getPastPosition(o)
if not p then return nil end

local q=(n-p).Unit
local r=(n-ac).Magnitude
return ac+q*r
end

local function closetMissBySpread(ac,n,o)
if not cfg.miss_by_spread then return nil end
if i:NextInteger(1,100)>cfg.miss_by_spread_chance then return nil end
local p=(o and(o:GetAttribute"Spread"or o:GetAttribute"BulletSpread"or o:GetAttribute"Accuracy"))or 2
p=p*(cfg.miss_by_spread_scale or 1.0)
local q=(n-ac).Magnitude

local r=math.tan(math.rad(p))*q
local s=i:NextNumber()*math.pi*2
local t=i:NextNumber()*r
Vector3.new(1,0,0)
local u=(n-ac).Unit

local v=math.abs(u.Y)<0.99 and Vector3.new(0,1,0)or Vector3.new(1,0,0)
local w=u:Cross(v).Unit
local x=u:Cross(w).Unit
local y=(w*math.cos(s)+x*math.sin(s))*t
return n+y
end

local function closetMissByDistance(ac,n,o)
if not cfg.miss_by_distance then return nil end
local p=(n-ac).Magnitude
local q=cfg.miss_by_distance_safe or 60
local r=cfg.miss_by_distance_far or 150
local s=cfg.miss_by_distance_near_chance or 10
local t=cfg.miss_by_distance_far_chance or 70

local u=math.clamp((p-q)/math.max(r-q,1),0,1)
local v=s+(t-s)*u
if i:NextInteger(1,100)>v then return nil end

local w=math.lerp and math.lerp(2,12,u)or(2+10*u)
local x=i:NextNumber()*math.pi*2
local y=i:NextNumber()*w
return n+Vector3.new(math.cos(x)*y,(i:NextNumber()-0.5)*w,math.sin(x)*y)
end

function getClosetMissPos(ac,n,o)
local p
p=closetMissByMovement(ac,n)
if p then return p end
p=closetMissBySpread(ac,n,o)
if p then return p end
p=closetMissByDistance(ac,n,o)
if p then return p end
return nil
end

