function modGun(p)
if not p or not p:IsA"Tool"then return end
if not _G.gunmod_enabled then return end
p:SetAttribute("FireRate",_G.gunmod_firerate)
p:SetAttribute("AutoFire",_G.gunmod_autofire)
p:SetAttribute("SpreadRadius",_G.gunmod_spread)
p:SetAttribute("Range",_G.gunmod_range)
end

function isGunModTarget(p)
for q,r in pairs(cfg.gunmodsselected)do
if r and q==p then return true end
end
return false
end

function applyGunMods()
if not _G.gunmod_enabled then return end

if _G.gunmod_specific_enabled and currentGun then
if not(_G.gunmod_specific_tools and _G.gunmod_specific_tools[currentGun.Name])then
return
end
end
local p=LocalPlayer.Character
local q=LocalPlayer:FindFirstChild"Backpack"
local r={}
if p then table.insert(r,p)end
if q then table.insert(r,q)end
for s,t in ipairs(r)do
for u,w in ipairs(t:GetChildren())do
if w:IsA"Tool"and isGunModTarget(w.Name)then
moddedTools[w]=true
modGun(w)
end
end
end
end

function scanBackpack()
applyGunMods()
end

function setupGunMods()
local p=LocalPlayer:FindFirstChild"Backpack"
if not p then return end
p.ChildAdded:Connect(function(q)
if q:IsA"Tool"and isGunModTarget(q.Name)then
task.wait(0.05)
moddedTools[q]=true
modGun(q)
end
end)
end

LocalPlayer.CharacterAdded:Connect(function(p)
task.wait(0.5)
applyGunMods()

p.ChildAdded:Connect(function(q)
if q:IsA"Tool"and isGunModTarget(q.Name)then
task.wait(0.05)
moddedTools[q]=true
modGun(q)
end
end)
end)

task.spawn(function()
while true do
task.wait(0.5)
if _G.gunmod_enabled then
for p in pairs(moddedTools)do
if p and p.Parent then
modGun(p)
else
moddedTools[p]=nil
end
end
end
end
end)

function getGun()
local p=LocalPlayer.Character
if not p then return nil end
for q,r in ipairs(p:GetChildren())do
if r:IsA"Tool"and r:GetAttribute"ToolType"=="Gun"then
return r
end
end
return nil
end

