local function _sa_noUpvals(C)
return function(...)return C(...)end
end

local function _sa_isTaser(C)
return C and(C:GetAttribute"Behavior"=="Taser"or C:GetAttribute"Projectile"=="Taser")
end
local function _sa_isSniper(C)
return C and C:GetAttribute"Behavior"=="Sniper"
end
local function _sa_isShotgun(C)
return C and(C:GetAttribute"IsShotgun"or C:GetAttribute"Behavior"=="Shotgun")
end
local function _sa_sniperStable(C)
