if UserInputService.MouseBehavior~=Enum.MouseBehavior.LockCenter then return false end
local D=LocalPlayer.Character
local E=D and D:FindFirstChildOfClass"Humanoid"
return not E or E:GetState()~=Enum.HumanoidStateType.Freefall
end

local function setupCastRayHook()
local C=filtergc("function",{Name="castRay"},true)
if not C then return false end

_G._sa_origCastRay=hookfunction(C,_sa_noUpvals(function(D,E,...)

if not cfg.enabled or _G.resolverShootBlock then
return _G._sa_origCastRay(D,E,...)
end

if not currentGun or currentGun.Parent~=LocalPlayer.Character then
return _G._sa_origCastRay(D,E,...)
end

local F=getClosest(cfg.fov)
if not F or not F.Character then
return _G._sa_origCastRay(D,E,...)
end

local G=getTargetPart(F.Character)
if not G then
return _G._sa_origCastRay(D,E,...)
end

local H=currentGun:GetAttribute"Range"
if H and(G.Position-D).Magnitude>H+5 then
return _G._sa_origCastRay(D,E,...)
end

local I=_sa_isTaser(currentGun)
local J=_sa_isShotgun(currentGun)
local K=_sa_isSniper(currentGun)

if cfg.shotgungamehandled and J then
return _G._sa_origCastRay(D,G.Position,...)
end

local L=false

local M=false
if _G.fov_inner_alwayshit and not(_G.fov_inner_cosmetic)and _G.fov_inner_enabled and cfg.sa_type=="Mouse"then
local N=UserInputService:GetMouseLocation()
local O=workspace.CurrentCamera and workspace.CurrentCamera:WorldToViewportPoint(G.Position)
if O then
local P=N.X-O.X
local Q=N.Y-O.Y
local R=(_G.fov_inner_size or 20)*0.5
M=(P*P+Q*Q)<=(R*R)
end
end
if M then
L=true
elseif cfg.taseralwayshit and I then
L=true
elseif cfg.ifplayerstill and isStanding(F)then
L=true
elseif cfg.hitchanceAutoOnly and not currentGun:GetAttribute"AutoFire"then
L=true
else
L=rollHit()
end

if L then
if K and not _sa_sniperStable(currentGun)then
return _G._sa_origCastRay(D,G.Position,...)
end

if I or(J and cfg.shotgunnaturalspread)then
return _G._sa_origCastRay(D,G.Position,...)
end

return G,G.Position
else

local N=getClosetMissPos(D,G.Position,currentGun)
if N then
return _G._sa_origCastRay(D,N,...)
end
if cfg.missspread>0 then
local O=getMissPos(G.Position)
return _G._sa_origCastRay(D,O,...)
end
return _G._sa_origCastRay(D,E,...)
end
end))
return true
end

if not setupCastRayHook()then
task.spawn(function()
while not _G._sa_hooked do
task.wait(0.5)
if setupCastRayHook()then
_G._sa_hooked=true
end
end
end)
else
_G._sa_hooked=true
end

