local Q=Vector3.new(math.cos(P),0,math.sin(P))
for R,S in ipairs{0.25,0.5,0.75,1.0}do
table.insert(N,Q*M*S)
end
end

for O,P in ipairs{4,8,12}do
table.insert(N,Vector3.new(0,P,0))
end

for O,P in ipairs{-4,-8,-12}do
table.insert(N,Vector3.new(0,P,0))
end

for O=0,315,90 do
local P=math.rad(O)
local Q=Vector3.new(math.cos(P),0,math.sin(P))
for R,S in ipairs{5,10}do
table.insert(N,Q*M*0.5+Vector3.new(0,S,0))
end
end

for O=0,315,90 do
local P=math.rad(O)
local Q=Vector3.new(math.cos(P),0,math.sin(P))
for R,S in ipairs{-5,-10}do
table.insert(N,Q*M*0.5+Vector3.new(0,S,0))
end
end

for O,P in ipairs(N)do
local Q=J+P

if math.abs(P.Y)<3 then
local R=workspace:Raycast(Q+Vector3.new(0,6,0),Vector3.new(0,-25,0),C)
if R then Q=R.Position+Vector3.new(0,3,0)end
end

if P.Y<-3 then

local R=workspace:Raycast(Q,Vector3.new(0,2,0),C)
if R then Q=R.Position+Vector3.new(0,0.5,0)end
end

local R=(Q-I).Magnitude

if R>=6 and resolverHasLOS(Q,I,K)then

if not resolverIsThickWall(Q,I,K)then
table.insert(L,{
pos=Q,
travelDist=(Q-J).Magnitude,
})
end
end
end

if#L==0 then return nil end

local O=_G.resolver_pos_mode or"closest"
if O=="farthest"then

table.sort(L,function(P,Q)return P.travelDist>Q.travelDist end)
else

table.sort(L,function(P,Q)return P.travelDist<Q.travelDist end)
end
return L[1].pos
end

