local function _fp_updateViewers()
if not _G.fp_viewerdetect then return end
local ad=LocalPlayer.Character
if not ad then return end
local ae=ad:FindFirstChild"HumanoidRootPart"
if not ae then return end

for af,ag in pairs(f:GetPlayers())do
if ag==LocalPlayer then continue end

local ah=false
pcall(function()
local ai=workspace.CurrentCamera
if ai.CameraSubject and ai.CameraSubject:IsDescendantOf(ad)then
ah=true
end
end)
if not ah and ag.Character then
local ai=ag.Character:FindFirstChild"HumanoidRootPart"
if ai then
local F=(ae.Position-ai.Position)
local G=F.Magnitude
if G<200 then
local H=workspace.CurrentCamera.CFrame.LookVector
local I=math.acos(math.clamp(F.Unit:Dot(H),-1,1))
if I<math.rad(15)then ah=true end
end
end
end
if ah and not _G._fp_knownViewers[ag.Name]then
_G._fp_knownViewers[ag.Name]=true
safeNotify("[FakePos] viewer: "..ag.Name,3)
if _G.fp_viewerHL and _G.fp_viewerdetect and ag.Character then
local ai=Instance.new"Highlight"
ai.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
ai.FillColor=_G.fp_viewerHLcolor or Color3.fromRGB(255,50,50)
ai.FillTransparency=0.3
ai.OutlineColor=Color3.fromRGB(255,255,255)
ai.Adornee=ag.Character
ai.Parent=ag.Character
_G._fp_viewerHL_cache[ag.Name]=ai
end
elseif not ah and _G._fp_knownViewers[ag.Name]then
_G._fp_knownViewers[ag.Name]=nil
if _G._fp_viewerHL_cache[ag.Name]then
pcall(function()_G._fp_viewerHL_cache[ag.Name]:Destroy()end)
_G._fp_viewerHL_cache[ag.Name]=nil
end
end
end
end

