function fp_teleportAndRestore(ad,ae,af,ag)
local ah=LocalPlayer.Character
local ai=ah and ah:FindFirstChild"HumanoidRootPart"
if not ai then return false end

local F=ai.CFrame
_G.fp_lastSafe=F

local G=_G.fp_enabled
_G.fp_enabled=true

ai.CFrame=CFrame.new(ad)*(F-F.Position)

RunService:BindToRenderStep("FP_TeleRestore",199,function()
if ai and ai.Parent then ai.CFrame=F end
RunService:UnbindFromRenderStep"FP_TeleRestore"
end)

task.spawn(function()
if af then pcall(af)end
task.wait(ae or 2)
if ai and ai.Parent then
ai.CFrame=F
end
_G.fp_enabled=G
if ag then pcall(ag)end
end)
return true
end

