local function _ug_updateViewers()
if not _G.ug_viewerdetect then return end
local ad=LocalPlayer.Character
if not ad then return end
local ae=ad:FindFirstChild"HumanoidRootPart"
if not ae then return end
for af,ag in pairs(f:GetPlayers())do
if ag==LocalPlayer then continue end
local ah=false
