local F=(ae.Position-ai.Position)
if F.Magnitude<250 then
local G=math.acos(math.clamp(F.Unit:Dot(workspace.CurrentCamera.CFrame.LookVector),-1,1))
if G<math.rad(20)then ah=true end
end
end
end
if ah and not _G._ug_knownViewers[ag.Name]then
_G._ug_knownViewers[ag.Name]=true
safeNotify("[Underground] watcher: "..ag.Name,3)
elseif not ah and _G._ug_knownViewers[ag.Name]then
_G._ug_knownViewers[ag.Name]=nil
end
end
end

_G.ug_active=false
_G._ug_conn=nil
_G._ug_restoreConn=nil
_G._ug_goalCF=nil

function undergroundActivate()
if not _G.ug_enabled then return end

if _G.ug_active then
_G.ug_active=false
if _G._ug_conn then _G._ug_conn:Disconnect();_G._ug_conn=nil end
if _G._ug_restoreConn then _G._ug_restoreConn:Disconnect();_G._ug_restoreConn=nil end
_G._ug_goalCF=nil
if _G._ug_line then _G._ug_line.Visible=false end
if _G._ug_hl then pcall(function()_G._ug_hl:Destroy()end);_G._ug_hl=nil end
if _G._ug_part then pcall(function()_G._ug_part:Destroy()end);_G._ug_part=nil end
_G.fp_enabled=false
pcall(_fp_hideVisuals)
if _G._fp_DesyncLine then _G._fp_DesyncLine.Visible=false end
safeNotify("underground: OFF",2)
return
end

local ad=LocalPlayer.Character
local ae=ad and ad:FindFirstChild"HumanoidRootPart"
if not ae then return end

local af,ag=math.huge
for ah,ai in ipairs(f:GetPlayers())do
if ai~=LocalPlayer and ai.Character then
local F=ai.Character:FindFirstChildOfClass"Humanoid"
if F and F.Health>0 then
if not(cfg.teamcheck and ai.Team==LocalPlayer.Team)then
local G=ai.Character:FindFirstChild"HumanoidRootPart"
if G then
local H=(G.Position-ae.Position).Magnitude
if H<af then af=H;ag=ai end
end
end
end
end
end

if not ag then safeNotify("underground: no target",2);return end
local ah=ag.Character and ag.Character:FindFirstChild"HumanoidRootPart"
if not ah then return end

local ai=_G.ug_depth or 8
local F=ah.Position-Vector3.new(0,ai,0)
local G=CFrame.new(F)
*CFrame.Angles(
math.rad(_G.ug_rotX or 0),
math.rad(_G.ug_rotY or 0),
math.rad(_G.ug_rotZ or 0)
)
_G._ug_goalCF=G
_G.ug_active=true

safeNotify("underground: ON ("..math.floor(ai).." studs)",2)

if not _G._ug_line then
local H=Drawing.new"Line"
H.Visible=false;H.Thickness=2;H.ZIndex=10
H.Color=Color3.fromRGB(80,100,255)
_G._ug_line=H
end
if not _G._ug_part then
local H=Instance.new"Part"
H.Name="_UG_FakePart"
H.Size=Vector3.new(4,5,2)
H.Anchored=true
H.CanCollide=false
H.Transparency=0.5
H.CastShadow=false
H.Parent=workspace
_G._ug_part=H
end

if _G._ug_hl then pcall(function()_G._ug_hl:Destroy()end);_G._ug_hl=nil end
local H=Instance.new"Highlight"
H.FillColor=_G.ug_clonecolor or Color3.fromRGB(100,100,255)
H.OutlineColor=_G.ug_outlinecolor or Color3.fromRGB(200,200,255)
H.FillTransparency=_G.ug_transparency or 0.5
H.OutlineTransparency=0
H.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
H.Enabled=false
H.Parent=workspace
_G._ug_hl=H

_G._ug_conn=RunService.Heartbeat:Connect(function()
if not _G.ug_active or not _G.ug_enabled then
if _G._ug_conn then _G._ug_conn:Disconnect();_G._ug_conn=nil end
_G.ug_active=false
if _G._ug_line then _G._ug_line.Visible=false end
if _G._ug_hl then pcall(function()_G._ug_hl:Destroy()end);_G._ug_hl=nil end
return
end

local I=LocalPlayer.Character
local J=I and I:FindFirstChild"HumanoidRootPart"
if not J then return end

local K=J.CFrame
local L=_G.ug_depth or ai
G=K
*CFrame.new(0,-L,0)
*CFrame.Angles(
math.rad(_G.ug_rotX or 0),
math.rad(_G.ug_rotY or 0),
math.rad(_G.ug_rotZ or 0)
)
F=G.Position
_G._ug_goalCF=G

J.CFrame=G

if _G._ug_part then
_G._ug_part.CFrame=G

_G._ug_part.Size=Vector3.new(4,5,2)
_G._ug_part.Transparency=0.5
end
if _G._ug_hl then
_G._ug_hl.FillColor=_G.ug_clonecolor or Color3.fromRGB(100,100,255)
_G._ug_hl.OutlineColor=_G.ug_outlinecolor or Color3.fromRGB(200,200,255)
_G._ug_hl.FillTransparency=_G.ug_transparency or 0.5
_G._ug_hl.Enabled=true
_G._ug_hl.Adornee=_G._ug_part
end

if _G.ug_showline~=false and _G._ug_line then
local M=workspace.CurrentCamera
local N,O=M:WorldToViewportPoint(K.Position)
local P,Q=M:WorldToViewportPoint(F)
if O and Q then
_G._ug_line.From=Vector2.new(N.X,N.Y)
_G._ug_line.To=Vector2.new(P.X,P.Y)
_G._ug_line.Color=_G.ug_linecolor or Color3.fromRGB(80,100,255)
_G._ug_line.Thickness=_G.ug_linethickness or 2
_G._ug_line.Visible=true
else
_G._ug_line.Visible=false
end
elseif _G._ug_line then
_G._ug_line.Visible=false
end

RunService:BindToRenderStep("UG_Restore",199,function()
if J and J.Parent then J.CFrame=K end
RunService:UnbindFromRenderStep"UG_Restore"
end)

if math.floor(tick()*10)%5==0 then pcall(_ug_updateViewers)end
end)
end

