local function _applyGunModelColor(ad)
if not ad or not _G.gunhl_model_enabled then return end
for ae,af in ipairs(ad:GetDescendants())do
if af:IsA"BasePart"then
if not _G._gunOrigParts[af]then
_G._gunOrigParts[af]={c=af.Color,t=af.Transparency,m=af.Material}
end
pcall(function()
af.Color=_G.gunhl_model_color
af.Transparency=_G.gunhl_model_trans
af.Material=Enum.Material[_G.gunhl_model_material]
end)
end
end
end

local function _restoreGunModel()
for ad,ae in pairs(_G._gunOrigParts)do
pcall(function()
if ad and ad.Parent then
ad.Color=ae.c;ad.Transparency=ae.t;ad.Material=ae.m
end
end)
end
