function _aaStart()
_aaStop()
_G._aaCamJitterT=0
_G._aaConn=RunService.Heartbeat:Connect(function(ae)
if not _G.aa_enabled then _aaStop();return end
local af=LocalPlayer.Character
if not af then return end
local ag=af:FindFirstChild"HumanoidRootPart"
if not ag then return end
local ah=af:FindFirstChildOfClass"Humanoid"
local ai=workspace.CurrentCamera

local F=_G.aa_mode or"jitter"

if F=="jitter"then
if ah then ah.AutoRotate=false end

local G=ag.AssemblyLinearVelocity.Magnitude
local H=_G.aa_jitter_fast_freq or 1
local I=_G.aa_jitter_slow_freq or 8
local J=(_G.aa_jitter_slow_nomove and G<2)and I or H
_G._aa_jitter_fc=(_G._aa_jitter_fc or 0)+1
if _G._aa_jitter_fc>=J then
_G._aa_jitter_fc=0
local K=_G.aa_jitter_mode or"random"
local L=0
local M=_G.aa_jitter_angle or 60
if K=="random"then
L=math.rad(math.random(-M,M))
elseif K=="2way"then

_G._aa_jitter_state=((_G._aa_jitter_state or 0)+1)%2
L=math.rad(_G._aa_jitter_state==0 and-M or M)
elseif K=="3way"then

_G._aa_jitter_state=((_G._aa_jitter_state or 0)+1)%3
local N={-180,90,180}
L=math.rad(N[_G._aa_jitter_state+1])
elseif K=="sway"then

_G._aa_jitter_sway_t=(_G._aa_jitter_sway_t or 0)+0.18
L=math.rad(math.sin(_G._aa_jitter_sway_t)*M)
elseif K=="zigzag"then

_G._aa_jitter_state=((_G._aa_jitter_state or 0)+1)%4
local N={-M,-M/2,M/2,M}
L=math.rad(N[_G._aa_jitter_state+1])
elseif K=="circle"then

_G._aa_jitter_sway_t=(_G._aa_jitter_sway_t or 0)+0.25
L=_G._aa_jitter_sway_t
end
if ai then
local N=Vector3.new(ai.CFrame.LookVector.X,0,ai.CFrame.LookVector.Z)
if N.Magnitude>0.01 then
local O=CFrame.fromAxisAngle(Vector3.new(0,1,0),L)
ag.CFrame=CFrame.new(ag.Position,ag.Position+O*N.Unit)
end
end
end

elseif F=="spin"then
if ah then ah.AutoRotate=false end
_G._aaSpinAngle=(_G._aaSpinAngle+_G.aa_spin_speed*ae*60)%360
if ai then
local G=Vector3.new(ai.CFrame.LookVector.X,0,ai.CFrame.LookVector.Z)
if G.Magnitude>0.01 then
local H=CFrame.fromAxisAngle(Vector3.new(0,1,0),math.rad(_G._aaSpinAngle))
ag.CFrame=CFrame.new(ag.Position,ag.Position+H*G.Unit)
end
end

elseif F=="reverse"then
if ah then ah.AutoRotate=false end
if ai then
local G=Vector3.new(ai.CFrame.LookVector.X,0,ai.CFrame.LookVector.Z)
if G.Magnitude>0.01 then
ag.CFrame=CFrame.new(ag.Position,ag.Position-G.Unit)
end
end

elseif F=="protect"then
if ah then ah.AutoRotate=false end

_G._protect_tick=(_G._protect_tick or 0)+1
if _G._protect_tick%6==0 then
local G=af:FindFirstChild"Head"
if G then
local H=12
local I=RaycastParams.new()
I.FilterType=Enum.RaycastFilterType.Exclude
I.FilterDescendantsInstances={af}

local J={}
for K,L in ipairs(f:GetPlayers())do
if L~=LocalPlayer and L.Character then
local M=L.Character:FindFirstChild"Head"
or L.Character:FindFirstChild"HumanoidRootPart"
if M then table.insert(J,M)end
end
end
local K
local L=-math.huge
for M=0,H-1 do
local N=math.rad(M*(360/H))
local O=Vector3.new(math.cos(N),0,math.sin(N))
local P=0
for Q,R in ipairs(J)do
local S=Vector3.new(
G.Position.X-R.Position.X,0,
G.Position.Z-R.Position.Z)
if S.Magnitude>0.5 then
P=P-O:Dot(S.Unit)

local T=workspace:Raycast(
G.Position,R.Position-G.Position,I)
if T and T.Instance then P=P+4 end
end
end
if P>L then
L=P;K=N
end
end
_G._protect_bestAngle=K
end
end

if _G._protect_bestAngle then
local G=Vector3.new(math.cos(_G._protect_bestAngle),0,math.sin(_G._protect_bestAngle))
local H=Vector3.new(ag.CFrame.LookVector.X,0,ag.CFrame.LookVector.Z)
local I=(H.Magnitude>0.01 and H.Unit or G):Lerp(G,0.15)
if I.Magnitude>0.01 then
ag.CFrame=CFrame.new(ag.Position,ag.Position+I)
end
end

elseif F=="camera"then

if ah then ah.AutoRotate=false end
if ai then
local G=Vector3.new(ai.CFrame.LookVector.X,0,ai.CFrame.LookVector.Z)
if G.Magnitude>0.01 then
ag.CFrame=CFrame.new(ag.Position,ag.Position+G.Unit)
end
end

elseif F=="camjitter"then

if ah then ah.AutoRotate=true end
_G._aaCamJitterT=_G._aaCamJitterT+ae*_G.aa_camjitter_speed
if ai then
local G=math.sin(_G._aaCamJitterT)*_G.aa_camjitter_angle
local H=math.rad(G)

local I=ai.CFrame
local J=I*CFrame.fromAxisAngle(Vector3.new(0,1,0),H)
ai.CFrame=CFrame.new(I.Position)*(J-J.Position)
end

elseif F=="desync"then

if ah then ah.AutoRotate=false end
if ai then
local G=Vector3.new(ai.CFrame.LookVector.X,0,ai.CFrame.LookVector.Z)
if G.Magnitude>0.01 then

ag.CFrame=CFrame.new(ag.Position,ag.Position-G.Unit)
end
end

elseif F=="spinreverse"then

if ah then ah.AutoRotate=false end
_G._aaSpinAngle=(_G._aaSpinAngle+_G.aa_spin_speed*ae*60)%360
if ai then
local G=Vector3.new(ai.CFrame.LookVector.X,0,ai.CFrame.LookVector.Z)
if G.Magnitude>0.01 then
local H=CFrame.fromAxisAngle(Vector3.new(0,1,0),math.rad(_G._aaSpinAngle+180))
ag.CFrame=CFrame.new(ag.Position,ag.Position+H*G.Unit)
end
end

elseif F=="oscillate"then

if ah then ah.AutoRotate=false end
_G._aaOscT=(_G._aaOscT or 0)+ae*(_G.aa_osc_speed or 3)
local G=math.sin(_G._aaOscT)*180
if ai then
local H=Vector3.new(ai.CFrame.LookVector.X,0,ai.CFrame.LookVector.Z)
if H.Magnitude>0.01 then
local I=CFrame.fromAxisAngle(Vector3.new(0,1,0),math.rad(G))
ag.CFrame=CFrame.new(ag.Position,ag.Position+I*H.Unit)
end
end

elseif F=="twitch"then

if ah then ah.AutoRotate=false end
local G=math.rad(math.random(-180,180))
if ai then
local H=Vector3.new(ai.CFrame.LookVector.X,0,ai.CFrame.LookVector.Z)
if H.Magnitude>0.01 then
local I=CFrame.fromAxisAngle(Vector3.new(0,1,0),G)
ag.CFrame=CFrame.new(ag.Position,ag.Position+I*H.Unit)
end
end
end
end)
end

