local function loadAnimJson(af)
if not(isfile and readfile)then
return
end

if not isfile(af)then
warn("Missing animation json: "..af)
return
end

local ag,ah=pcall(function()
return ae:JSONDecode(readfile(af))
end)

if not ag or type(ah)~="table"then
warn("Failed to parse "..af)
return
end

for ai,F in ipairs(ah)do
if type(F)=="table"and F.name and F.id then
if not _G.animplayer_ids[F.name]then
_G.animplayer_ids[F.name]=F.id
end
end

if ai%25==0 then
task.wait()
end
end


end

task.spawn(function()
loadAnimJson"r6.json"
end)

_G.animplayer_game_anims={}
_G.animplayer_detected_names={}

local function _scanGameAnims()
_G.animplayer_game_anims={}
_G.animplayer_detected_names={}
local af={}
local function scanDesc(ag)
for ah,ai in ipairs(ag:GetDescendants())do
if ai:IsA"Animation"and ai.AnimationId~=""and not af[ai.AnimationId]then
af[ai.AnimationId]=true
local F=ai.Name~=""and ai.Name or("Anim_"..tostring(#_G.animplayer_detected_names+1))

local G=F
local H=1
while _G.animplayer_game_anims[F]do F=G.."_"..H;H=H+1 end
_G.animplayer_game_anims[F]=ai.AnimationId
table.insert(_G.animplayer_detected_names,F)
end
end
end
pcall(function()scanDesc(game:GetService"ReplicatedStorage")end)
pcall(function()scanDesc(game:GetService"Workspace")end)

local ag=LocalPlayer.Character
if ag then
local ah=ag:FindFirstChildOfClass"Humanoid"
local ai=ah and(ah:FindFirstChildOfClass"Animator"or ah:FindFirstChildOfClass"AnimationController")
if ai then
for F,G in ipairs(ai:GetPlayingAnimationTracks())do
local H=G.Animation and G.Animation.AnimationId or""
if H~=""and not af[H]then
af[H]=true
local I="playing_"..tostring(#_G.animplayer_detected_names+1)
_G.animplayer_game_anims[I]=H
table.insert(_G.animplayer_detected_names,I)
end
end
end
end
safeNotify("found "..(#_G.animplayer_detected_names).." anims",2)

if Options and Options.AnimPlayerSelect then
local ah={}
for ai,F in ipairs(_G.animplayer_detected_names)do table.insert(ah,F)end
for ai in pairs(_G.animplayer_ids)do table.insert(ah,ai)end
Options.AnimPlayerSelect.Values=ah

if Options.AnimPlayerSelect.BuildDropdownList then
pcall(function()Options.AnimPlayerSelect:BuildDropdownList()end)
elseif Options.AnimPlayerSelect.SetValues then
pcall(function()Options.AnimPlayerSelect:SetValues(ah)end)
end
end
end
