local F,G,H=1.000,1.065,0.15
local I=true
ai:Play();task.wait(0.1)
ai.TimePosition=F;ai:AdjustSpeed(H)
_G.goon_conn=RunService.RenderStepped:Connect(function()
if not _G.goon_enabled or not ai.IsPlaying then return end
if I then
if ai.TimePosition>=G then I=false;ai:AdjustSpeed(-H)end
else
if ai.TimePosition<=F then I=true;ai:AdjustSpeed(H)end
end
end)
_G._goon_track=ai
end

