local function _strafeStop()
_G._strafeActive=false
_G._strafeTarget=nil
if _G._strafeHL then _G._strafeHL:Destroy();_G._strafeHL=nil end
local ah=LocalPlayer.Character
if ah then
local ai=ah:FindFirstChildOfClass"Humanoid"
if ai then

if _G._strafeOrigSpeed then
ai.WalkSpeed=_G._strafeOrigSpeed
_G._strafeOrigSpeed=nil
end
ai:MoveTo(ai.RootPart and ai.RootPart.Position or ah:FindFirstChild"HumanoidRootPart"and ah.HumanoidRootPart.Position or Vector3.new())
end
end

if _G.targetstrafe_noaccel and _G.noAccelConnection then
_G.noAccelConnection:Disconnect()
_G.noAccelConnection=nil
end
end

local function _strafeFindTarget()
local ah=LocalPlayer.Character
local ai=ah and ah:FindFirstChild"HumanoidRootPart"
if not ai then return nil end
local F,G=math.huge
for H,I in ipairs(f:GetPlayers())do
if I~=LocalPlayer and I.Character then
local J=I.Character:FindFirstChild"HumanoidRootPart"
local K=I.Character:FindFirstChildOfClass"Humanoid"
if J and K and K.Health>0 then
local L=_G.targetstrafe_teamcheck and(I.Team==LocalPlayer.Team)
if not L then
local M=(ai.Position-J.Position).Magnitude
if M<F then F=M;G=I end
end
end
end
end
return G
end

local function _strafeLoop()
while _G._strafeActive and _G._strafeTarget do
local ah=LocalPlayer.Character
local ai=ah and ah:FindFirstChild"HumanoidRootPart"
local F=ah and ah:FindFirstChildOfClass"Humanoid"
if not ai or not F then _strafeStop();break end

local G=_G.targetstrafe_useownspeed and F.WalkSpeed or _G.targetstrafe_speed
if _G._strafeOrigSpeed==nil then
_G._strafeOrigSpeed=F.WalkSpeed
end
F.WalkSpeed=G

if _G.targetstrafe_noaccel and not _G.noAccelConnection then
_G.noAccelConnection=RunService.RenderStepped:Connect(function()
if not F or F.Health<=0 then return end
if F.SeatPart then return end
local H=F.MoveDirection
if H.Magnitude>0 then
ai.AssemblyLinearVelocity=Vector3.new(H.X*G,ai.AssemblyLinearVelocity.Y,H.Z*G)
end
end)
end

local H=_G._strafeTarget and _G._strafeTarget.Character
local I=H and H:FindFirstChild"HumanoidRootPart"
if not I then _strafeStop();break end

local J=I.Position
if(ai.Position-J).Magnitude>4 then
local K=pcall(function()ag:ComputeAsync(ai.Position,J)end)
if K and ag.Status==Enum.PathStatus.Success then
local L=ag:GetWaypoints()
if L[2]then
F:MoveTo(L[2].Position)
if L[2].Action==Enum.PathWaypointAction.Jump then F.Jump=true end
end
else
F:MoveTo(J)
end
end
task.wait(0.1)
end
if _G._strafeActive then _strafeStop()end
end

local function _strafeToggle()
if _G._strafeActive then
_strafeStop()
else

local ah=_strafeFindTarget()
if not ah then return end
_G._strafeTarget=ah
_G._strafeActive=true

if ah.Character then
_G._strafeHL=Instance.new"Highlight"
_G._strafeHL.FillTransparency=1
_G._strafeHL.OutlineColor=Color3.fromRGB(255,50,50)
