local function _animLagStart()
local ah=game:GetService"Players"
local ai=game:GetService"RunService"
local F=ah.LocalPlayer

if typeof(_G._animLagConn)=="RBXScriptConnection"then
_G._animLagConn:Disconnect()
end
_G._animLagConn=nil
_G._animLagThread=nil

local function applyLag()
if not F then return end
local G=F.Character
if not G then return end

local H=G:FindFirstChildOfClass"Humanoid"
if not H then return end

local I=H:FindFirstChildOfClass"Animator"
if not I then return end

local J=I:GetPlayingAnimationTracks()
if not J then return end

for K,L in ipairs(J)do
if L and L.Length then
pcall(function()
local M=(L.Length>0 and L.Length)or 99

L:AdjustSpeed(0)

if _G.animlag_random then
L.TimePosition=math.clamp(
_G._animLagTimePos or 0,
0,
math.max(0.001,M-0.02)
)
else
local N=_G.animlag_step or 0.1
L.TimePosition=(L.TimePosition+N)%math.max(M-0.02,0.02)
end
end)
end
end
end

if _G.animlag_random then

_G._animLagConn=ai.Heartbeat:Connect(function()
if not _G.animlag_enabled then return end

local G=_G.animlag_random_min or 0
local H=_G.animlag_random_max or 1

if H<=G then
H=G+0.1
end

_G._animLagTimePos=G+math.random()*(H-G)

applyLag()
end)

else

_G._animLagThread=task.spawn(function()
while _G.animlag_enabled do
applyLag()
task.wait(_G.animlag_interval or 0.1)
end
end)

end
end

local function _animLagStop()
_G.animlag_enabled=false

if typeof(_G._animLagConn)=="RBXScriptConnection"then
_G._animLagConn:Disconnect()
end

_G._animLagConn=nil
_G._animLagThread=nil
end

_G._animLagStart=_animLagStart
_G._animLagStop=_animLagStop


























local ah={}
_G.muteguns_enabled=false

local function muteTool(ai)
for F,G in ipairs(ai:GetDescendants())do
if G:IsA"Sound"then
if not ah[G]then
ah[G]=G.Volume
end
G.Volume=0
end
end
end

local function unmuteTool(ai)
for F,G in ipairs(ai:GetDescendants())do
if G:IsA"Sound"and ah[G]then
G.Volume=ah[G]
ah[G]=nil
end
end
end

local function applyMute()
local function process(ai)
if not ai:IsA"Tool"then
return
end

if _G.muteguns_enabled then
muteTool(ai)
else
unmuteTool(ai)
end
end

local ai=LocalPlayer:FindFirstChild"Backpack"
if ai then
for F,G in ipairs(ai:GetChildren())do
process(G)
end

if not ai:FindFirstChild"_MuteConnection"then
local F=Instance.new"BoolValue"
F.Name="_MuteConnection"
F.Parent=ai

ai.ChildAdded:Connect(function(G)
if G:IsA"Tool"and _G.muteguns_enabled then
task.wait()
muteTool(G)
end
end)
end
end

local F=LocalPlayer.Character
if F then
for G,H in ipairs(F:GetChildren())do
process(H)
end

if not F:FindFirstChild"_MuteConnection"then
local G=Instance.new"BoolValue"
G.Name="_MuteConnection"
G.Parent=F

F.ChildAdded:Connect(function(H)
if H:IsA"Tool"and _G.muteguns_enabled then
task.wait()
muteTool(H)
end
end)
end
end
end

LocalPlayer.CharacterAdded:Connect(function(ai)
if not _G.muteguns_enabled then
return
end

task.wait(1)
applyMute()

ai.ChildAdded:Connect(function(F)
if F:IsA"Tool"and _G.muteguns_enabled then
task.wait()
muteTool(F)
end
end)
end)



