local function spawnHitmarker(ai)
if not _G.hitmarker_enabled then return end
if not _G._hmGui then return end
local aj=workspace.CurrentCamera
local ak=ai and(ai:FindFirstChild"HumanoidRootPart"or ai:FindFirstChild"UpperTorso")
if not ak or not aj then return end

