local an,ao=aj:WorldToViewportPoint(al)
if not ao then return end
local ap=math.max(an.Z,1)
local aq=math.max(10,am*60/ap)
local ar=Instance.new"Frame"
ar.BackgroundTransparency=1
ar.AnchorPoint=Vector2.new(0.5,0.5)
ar.Size=UDim2.new(0,aq,0,aq)
ar.Position=UDim2.new(0,an.X,0,an.Y)
ar.Parent=_G._hmGui
local F=Instance.new("ImageLabel",ar)
F.BackgroundTransparency=1
F.Size=UDim2.new(1,0,1,0)
F.Image=_G.hitmarker_decal or"rbxassetid://4645534174"
F.ImageColor3=_G.hitmarker_color or Color3.new(1,1,1)
F.ImageTransparency=0

local G=_G.hitmarker_duration or 0.4
local H=_G.hitmarker_anim or"fade"
task.spawn(function()
local I=os.clock()
local J=0
while os.clock()-I<G and ar and ar.Parent do
local K=(os.clock()-I)/G

if aj and aj.Parent then
local L,M=aj:WorldToViewportPoint(al)
if M then
local N=math.max(L.Z,1)
local O=math.max(10,am*60/N)
ar.Size=UDim2.new(0,O,0,O)
ar.Position=UDim2.new(0,L.X,0,L.Y)
aq=O
end
end
if H=="fade"then
F.ImageTransparency=K
elseif H=="spin"then
J=J+8
ar.Rotation=J
F.ImageTransparency=K*0.8
elseif H=="pulse"then
local L=aq*(1+0.4*math.sin(K*math.pi*4)*(1-K))
ar.Size=UDim2.new(0,L,0,L)
F.ImageTransparency=K
elseif H=="bounce"then
local L=aq*(1+0.3*(1-K))
ar.Size=UDim2.new(0,L,0,L)
F.ImageTransparency=math.clamp(K*1.5-0.3,0,1)
elseif H=="grow-fade"then
local L=aq*(1+K*0.8)
ar.Size=UDim2.new(0,L,0,L)
F.ImageTransparency=K
end
task.wait()
end
if ar and ar.Parent then ar:Destroy()end
end)
end
