end
if I.x<-5E-2 then I.x=1.05 end
if I.x>1.05 then I.x=-5E-2 end

local K=I.frame
K.Position=UDim2.new(I.x,0,I.y,0)
K.Rotation=I.rot

local L=0.12*math.sin(ar*1.3+I.driftPhase)
K.BackgroundTransparency=math.clamp(I.trans+L,0.08,0.88)
end
end)

_G._snowGui=am
end


flushNotifyQueue()
e:SetWatermarkVisibility(cfg.showwatermark)

local am=0
local an=60
local ao=tick()

local ap=0
RunService.RenderStepped:Connect(function(aq)
am=am+1
if(tick()-ao)>=1 then
an=am
am=0
ao=tick()
end

ap=ap+aq
if ap<0.25 then return end
ap=0
e:SetWatermark(string.format('reversal private | %d fps | %d killstreak',math.floor(an),sessionStats.currentStreak))
end)

