_G.autoreload_enabled=false
_G.autoreload_exec_method="Remote"
_G.autoreload_threshold=0
_G.autoreload_method="Local_CurrentAmmo"
_G.autoreload_allbackpack=false
_G._autoreload_conn=nil

local T=0
local function _doReload()

local U=os.clock()
if U-T<0.1 then return end
T=U

local V=LocalPlayer.Character
if not V then return end
local W=V:FindFirstChildOfClass"Humanoid"
if not W or W.Health<=0 then return end

local X=V:FindFirstChildOfClass"Tool"
local Y=LocalPlayer:FindFirstChild"Backpack"
local Z=_G.autoreload_exec_method or"Remote"

local function checkTool(_)
if not _ or not _:IsA"Tool"then return end
local as=_:GetAttribute(_G.autoreload_method or"Local_CurrentAmmo")
or _:GetAttribute"CurrentAmmo"
if as==nil or as>(_G.autoreload_threshold or 0)then return end


if not _.Parent or not _.Parent:IsA"Model"then
pcall(function()W:EquipTool(_)end)
task.wait(0.05)
end

if Z=="Remote"then

local at=false
if _G._cachedFuncReload then
at=pcall(function()_G._cachedFuncReload:InvokeServer()end)
end
if not at then

local au=_G._cachedGunRemotes
local av=au and au:FindFirstChild"FuncReload"
if av then at=pcall(function()av:InvokeServer()end)end
end
if not at then

pcall(function()
for au,av in ipairs(_:GetDescendants())do
local aw=string.lower(av.Name)
if aw:find"reload"then
if av:IsA"RemoteEvent"then
av:FireServer();break
elseif av:IsA"RemoteFunction"then
av:InvokeServer();break
end
end
end
end)
end
else

pcall(function()
local at=game:GetService"VirtualInputManager"
at:SendKeyEvent(true,Enum.KeyCode.R,false,game)
task.wait(0.03)
at:SendKeyEvent(false,Enum.KeyCode.R,false,game)
end)
end
end

if X then checkTool(X)end
if _G.autoreload_allbackpack and Y then
for as,at in ipairs(Y:GetChildren())do
if at:IsA"Tool"then checkTool(at)end
end
end
end

local as=Q
as:AddDropdown('AutoReloadExecMethod',{
Values={'VirtualInput','Remote'},
Default=2,Text='exec method',
Tooltip='virtualinput = press r key | remote = fire reload remote',
Callback=function(at)_G.autoreload_exec_method=at end
})
as:AddToggle('AutoReloadEnabled',{
Text='enable auto reload',Default=false,
Callback=function(at)
_G.autoreload_enabled=at
if at then
if _G._autoreload_conn then _G._autoreload_conn:Disconnect()end
_G._autoreload_conn=RunService.Heartbeat:Connect(function()
if not _G.autoreload_enabled then
_G._autoreload_conn:Disconnect();_G._autoreload_conn=nil
return
end
pcall(_doReload)
end)
else
if _G._autoreload_conn then
_G._autoreload_conn:Disconnect();_G._autoreload_conn=nil
end
end
end
})
as:AddDropdown('AutoReloadMethod',{
Values={'Local_CurrentAmmo','CurrentAmmo'},
Default=1,Text='ammo attribute',
Callback=function(at)_G.autoreload_method=at end
})
as:AddSlider('AutoReloadThreshold',{
Text='reload when ammo <=',Default=0,Min=0,Max=30,Rounding=0,
Callback=function(at)_G.autoreload_threshold=at end
})
