})
local aw=at:AddDependencyBox()
aw:SetupDependencies{{Toggles.NoConsumeEnabled,true}}

local function _buildNoConsumeList()
local U={}
local V=LocalPlayer and LocalPlayer.Character
local W=LocalPlayer and LocalPlayer:FindFirstChild"Backpack"
if V then for X,Y in ipairs(V:GetChildren())do if Y:IsA"Tool"then table.insert(U,Y.Name)end end end
if W then for X,Y in ipairs(W:GetChildren())do if Y:IsA"Tool"then table.insert(U,Y.Name)end end end
if#U==0 then U={"(no tools found)"}end
return U
end
local U=_buildNoConsumeList()
local V
V=aw:AddDropdown('NoConsumeToolList',{
Values=U,
Default={},
Multi=true,
Text='excluded tools (no consume)',
Tooltip='selected tools will NOT consume bullets',
Callback=function(W)
_G.no_consume_tools={}
if type(W)=='table'then
for X,Y in ipairs(W)do _G.no_consume_tools[Y]=true end
end
end
})
wait(1)
aw:AddButton{
Text='refresh tool list',
Func=function()
local W=_buildNoConsumeList()
if V and V.SetValues then V:SetValues(W)end
end,
DoubleClick=false,
Tooltip='refresh the tool list from current backpack'
}

