_G.ui_AutoShootGroup:AddToggle('AirStuckEnabled',{
Text='airstuck',Default=false,
Tooltip='hold keybind to freeze character mid-air while in air',
Callback=function(W)_G.airstuck_enabled=W end
})
local W=_G.ui_AutoShootGroup:AddDependencyBox()
W:SetupDependencies{{Toggles.AirStuckEnabled,true}}
W:AddLabel'airstuck hold key':AddKeyPicker('AirStuckKey',{
Default='Z',Mode='Hold',
Text='hold to freeze in air',
Callback=function(X)

end
})

do
local X=game:GetService"UserInputService"
X.InputBegan:Connect(function(Y,Z)
if Z then return end
if not _G.airstuck_enabled then return end
if Options and Options.AirStuckKey then
local _=Options.AirStuckKey.Value
if _ and Y.KeyCode==Enum.KeyCode[tostring(_)]then
if _G._airstuck_startHold then _G._airstuck_startHold()end
end
end
end)
X.InputEnded:Connect(function(Y)
if not _G.airstuck_enabled then return end
if Options and Options.AirStuckKey then
local Z=Options.AirStuckKey.Value
if Z and Y.KeyCode==Enum.KeyCode[tostring(Z)]then
if _G._airstuck_stopHold then _G._airstuck_stopHold()end
end
end
end)
end


_G._whitelist_players={}

local function _wl_getNames()
local X={}
for Y,Z in ipairs(f:GetPlayers())do
if Z~=LocalPlayer then table.insert(X,Z.Name)end
end
return X
end
local X=_G.ui_AutoShootGroup:AddDropdown('TargetWhitelist',{
Values=_wl_getNames(),Default={},Multi=true,
Text='whitelist (skip targeting)',
Tooltip='selected players will never be targeted by ragebot/silent aim/resolver',
Callback=function(X)
_G._whitelist_players={}
for Y,Z in pairs(X)do _G._whitelist_players[Y]=true end
end
})

f.PlayerAdded:Connect(function()if X then pcall(function()X:SetValues(_wl_getNames())end)end end)
f.PlayerRemoving:Connect(function()if X then pcall(function()X:SetValues(_wl_getNames())end)end end)


_G._priority_player=nil
_G._priority_players={}
local Y=_G.ui_AutoShootGroup:AddDropdown('TargetPriority',{
Values=_wl_getNames(),Default=1,Multi=true,
Text='priority target',
Tooltip='always target these players first (visibility checked). Multi-select supported.',
Callback=function(Y)
if type(Y)=="table"then
_G._priority_players={}
for Z,_ in pairs(Y)do
if _ then _G._priority_players[Z]=true end
end
_G._priority_player=next(_G._priority_players)
else
_G._priority_player=Y
_G._priority_players=Y and{[Y]=true}or{}
end
end
})
wait(1)
f.PlayerAdded:Connect(function()if Y then pcall(function()Y:SetValues(_wl_getNames())end)end end)
f.PlayerRemoving:Connect(function()if Y then pcall(function()Y:SetValues(_wl_getNames())end)end end)

