local function _buildGunModToolList()
local ax={}
local Z=LocalPlayer and LocalPlayer.Character
local _=LocalPlayer and LocalPlayer:FindFirstChild"Backpack"
if Z then
for ay,az in ipairs(Z:GetChildren())do
if az:IsA"Tool"then table.insert(ax,az.Name)end
end
end
if _ then
for ay,az in ipairs(_:GetChildren())do
if az:IsA"Tool"then
local aA=false
for aB,aC in ipairs(ax)do if aC==az.Name then aA=true;break end end
if not aA then table.insert(ax,az.Name)end
end
end
end
if#ax==0 then ax={"(no tools found)"}end
return ax
end

local ax
ax=_G.ui_GunModsGroup:AddDropdown('GunModToolList',{
Values=_buildGunModToolList(),
Default={},
Multi=true,
Text='tools to mod',
Tooltip='select which tools receive gun mods (requires specific tool mods only)',
Callback=function(ay)
_G.gunmod_specific_tools={}
if type(ay)=='table'then
for az,aA in ipairs(ay)do _G.gunmod_specific_tools[aA]=true end
end
if _G.gunmod_enabled and _G.gunmod_specific_enabled then applyGunMods()end
end
})

