end
aL.CharacterAdded:Connect(function()
repeat task.wait()until aL.Character:FindFirstChild'Humanoid'
for aM,aN in getconnections(aL.Character.Humanoid:GetPropertyChangedSignal'Jump')do
aN:Disconnect()
end
end)
e:Notify('No Jump CD Applied!',3)
end,
