Tooltip='play a sound when you kill someone',
Callback=function(a4)cfg.killsound=a4 end
})

_G.ui_KillSoundGroup:AddInput('KillSoundID',{
Default=cfg.killsoundid,
Numeric=false,
Finished=true,
Text='sound id',
Tooltip='rbxassetid:// format',
Placeholder='rbxassetid://5043636498',
Callback=function(a4)
if a4 and a4~=""then
cfg.killsoundid=a4
end
end
})

_G.ui_KillSoundGroup:AddSlider('KillSoundVolume',{
Text='sound volume',
Default=cfg.killsoundvolume,
Min=0,
Max=1,
Rounding=2,
Compact=false,
Callback=function(a4)cfg.killsoundvolume=a4 end
})

_G.ui_KillSoundGroup:AddToggle('KillSoundLibEnabled',{
Text='use sound library',
Default=cfg.killsound_lib_enabled,
Tooltip='use reversal sound library instead of custom id',
Callback=function(a4)cfg.killsound_lib_enabled=a4 end
})
do
local a4={}
for a5 in pairs(_G._soundLib)do table.insert(a4,a5)end
table.sort(a4)
_G.ui_KillSoundGroup:AddDropdown('KillSoundLibPick',{
Values=a4,Default=1,Multi=true,
Text='kill sound library',
Tooltip='select sounds — random one plays on kill, selecting previews it',
Callback=function(a5)
cfg.killsound_lib_picks={}
local a6
for a7,a8 in pairs(a5)do
if a8 then
table.insert(cfg.killsound_lib_picks,a7)
a6=a7
if _G._loadLibSound then _G._loadLibSound(a7)end
end
end
if a6 then _G._playLibSound(a6,cfg.killsoundvolume)end
end
})
end
_G.ui_KillSoundGroup:AddButton{
Text='test sound',
Func=function()
pcall(function()
if cfg.killsound_lib_enabled and cfg.killsound_lib_picks and#cfg.killsound_lib_picks>0 then
if _G._playLibSoundMulti then
_G._playLibSoundMulti(cfg.killsound_lib_picks,cfg.killsoundvolume or 0.5)
elseif _G._playLibSound then
_G._playLibSound(cfg.killsound_lib_picks[1],cfg.killsoundvolume or 0.5)
end
elseif cfg.killsoundid and cfg.killsoundid~=""then
local a4=Instance.new"Sound"
a4.SoundId=cfg.killsoundid
a4.Volume=cfg.killsoundvolume or 0.5
a4.Parent=workspace
a4:Play()
game:GetService"Debris":AddItem(a4,3)
end
end)
end,
DoubleClick=false,
Tooltip='preview the kill sound'
}

