safeNotify("gif watermark needs writefile/getcustomasset",3);return
end

task.spawn(function()
local a7="https://raw.githubusercontent.com/o0oooo-o0/reversal-gif/refs/heads/main/frame_%03d_delay-0.04s.png"
local a8=150
local a9="reversal-gif-icon"
if isfolder and not isfolder(a9)then makefolder(a9)end
local ba={}
for bb=0,a8-1 do
local bc=string.format("frame_%03d.png",bb)
local bd=a9 .."/"..bc
if not isfile(bd)then
local be,bf=pcall(game.HttpGet,game,string.format(a7,bb))
if be and bf then writefile(bd,bf)end
end
if isfile(bd)then
local be=getcustomasset(bd)
table.insert(ba,be)
end
if bb%10==0 then task.wait()end
end
if#ba==0 then safeNotify("gif frames failed to load",3);return end

local bb=Instance.new"ScreenGui"
bb.Name="GifWatermark";bb.ResetOnSpawn=false;bb.DisplayOrder=999
pcall(function()bb.Parent=game:GetService"CoreGui"end)
if not bb.Parent then bb.Parent=LocalPlayer:WaitForChild"PlayerGui"end
_G._gifwm_gui=bb

local bc=_G.gifwatermark_size or 120
local bd=Instance.new"ImageLabel"
bd.Size=UDim2.new(0,bc,0,bc)
bd.BackgroundTransparency=1;bd.ZIndex=1;bd.Parent=bb
local be=bd:Clone();be.ZIndex=2;be.Parent=bb
local bf,bg=bd,be
bf.Image=ba[1]

local bh=Vector2.new(_G.gifwatermark_posX or 100,_G.gifwatermark_posY or 100)
local bi=Vector2.new(_G.gifwatermark_velX or 4,_G.gifwatermark_velY or 3)

_G._gifwm_conn=RunService.Heartbeat:Connect(function()
if not _G.gifwatermark_enabled then return end
if _G.gifwatermark_uionly then
local bj=e and e.Toggled==true
if _G._gifwm_gui then _G._gifwm_gui.Enabled=bj end
if not bj then return end
end
local bj=_G.gifwatermark_size or 120
bd.Size=UDim2.new(0,bj,0,bj);be.Size=bd.Size
if _G.gifwatermark_dvd then
local bk=workspace.CurrentCamera.ViewportSize
bh=bh+bi
if bh.X<=0 or bh.X+bj>=bk.X then bi=Vector2.new(-bi.X,bi.Y)end
if bh.Y<=0 or bh.Y+bj>=bk.Y then bi=Vector2.new(bi.X,-bi.Y)end
bf.Position=UDim2.new(0,bh.X,0,bh.Y)
bg.Position=bf.Position
else
local bk=_G.gifwatermark_posX or 100
local bl=_G.gifwatermark_posY or 100
bf.Position=UDim2.new(0,bk,0,bl)
bg.Position=bf.Position
end
end)

_G._gifwm_animConn=task.spawn(function()
while _G.gifwatermark_enabled and _G._gifwm_gui and _G._gifwm_gui.Parent do
for bj=2,#ba do
if not _G.gifwatermark_enabled then break end
bg.Image=ba[bj]
task.wait()
bf.ZIndex=1;bg.ZIndex=2;bf,bg=bg,bf
task.wait(_G.gifwatermark_speed or 0.04)
end
bg.Image=ba[1];task.wait()
bf.ZIndex=1;bg.ZIndex=2;bf,bg=bg,bf
end
end)
end)
end

local function _stopGifWatermark()
_G.gifwatermark_enabled=false
if _G._gifwm_conn then _G._gifwm_conn:Disconnect();_G._gifwm_conn=nil end
_G._gifwm_animConn=nil
if _G._gifwm_gui then _G._gifwm_gui:Destroy();_G._gifwm_gui=nil end
end

