function _G.makeDraggable(a8,a9,ba,bb)
_G.dragging=false
_G.dragStart=Vector2.new(0,0)

a8.InputBegan:Connect(function(bc)
if bc.UserInputType==Enum.UserInputType.MouseButton2 then
_G._espPreview_offsets[a9]={0,0}
a8.Position=UDim2.new(0,ba,0,bb)

elseif bc.UserInputType==Enum.UserInputType.MouseButton1 then
_G.dragging=true
_G.dragStart=Vector2.new(
bc.Position.X-a8.AbsolutePosition.X,
bc.Position.Y-a8.AbsolutePosition.Y
)
end
end)

a8.InputEnded:Connect(function(bc)
if bc.UserInputType==Enum.UserInputType.MouseButton1 then
_G.dragging=false
end
end)

game:GetService"UserInputService".InputChanged:Connect(function(bc)
if _G.dragging and bc.UserInputType==Enum.UserInputType.MouseMovement then
local bd=bc.Position.X-_G.dragStart.X-_G._ePFrm.AbsolutePosition.X
local be=bc.Position.Y-_G.dragStart.Y-_G._ePFrm.AbsolutePosition.Y

local bf=bd-ba
local bg=be-bb

_G._espPreview_offsets[a9]={bf,bg}
a8.Position=UDim2.new(0,bd,0,be)
end
end)
end

