task.wait(1)

local function getMode(bp)
if not bp then return"Toggle"end

if typeof(bp.GetMode)=="function"then
local bq,br=pcall(function()
return bp:GetMode()
end)
if bq and br then
return br
end
end

if bp.Mode then
return bp.Mode
end

return"Toggle"
end

local function isKeyMatch(bp,bq)
if bp.UserInputType==Enum.UserInputType.Keyboard then
return bp.KeyCode.Name==bq
elseif bp.UserInputType==Enum.UserInputType.MouseButton1 then
return bq=='MouseButton1'
elseif bp.UserInputType==Enum.UserInputType.MouseButton2 then
return bq=='MouseButton2'
end
return false
end

local function _applyKeybindFix(bp,bq,br)
if not Options[bp]then return end

local bs=false

UserInputService.InputBegan:Connect(function(bt,bu)
if bu then return end

local bv=Options[bp]
if not bv or not bv.Value then return end

local bw=tostring(bv.Value)
if bw=='None'then return end
if not isKeyMatch(bt,bw)then return end

local bx=getMode(bv)

if bx=="Hold"then
if br then br(true)end

elseif bx=="Toggle"then
bs=not bs

if bq then
pcall(function()
bq:SetValue(bs)
end)
end

if br then br(bs)end

elseif bx=="Press"then
if br then br(true)end

elseif bx=="Always"then
if br then br(true)end
end
end)

UserInputService.InputEnded:Connect(function(bt,bu)
local bv=Options[bp]
if not bv or not bv.Value then return end

local bw=tostring(bv.Value)
if bw=='None'then return end
if not isKeyMatch(bt,bw)then return end

local bx=getMode(bv)

if bx=="Hold"then
if br then br(false)end
elseif bx=="Press"then
if br then br(false)end
end
end)
end

_applyKeybindFix('SilentAimKeybind',Toggles.SilentAim,function(bp)
cfg.enabled=bp
end)

_applyKeybindFix('AutoShootKeybind',Toggles.AutoShoot,function(bp)
cfg.autoshoot=bp
end)

_applyKeybindFix('NoclipKeybind',Toggles.Noclip,function(bp)
cfg.noclip=bp
setupNoclip()
