local function getInventoryGuns()
local br={'Auto-detect'}
local bs={}
local bt=LocalPlayer:FindFirstChild"Backpack"
local bu=LocalPlayer.Character
local bv={}
if bt then table.insert(bv,bt)end
if bu then table.insert(bv,bu)end
for bw,bx in ipairs(bv)do
for by,bz in ipairs(bx:GetChildren())do
if bz:IsA"Tool"and not bs[bz.Name]then
bs[bz.Name]=true
table.insert(br,bz.Name)
end
end
end
return br
end

