_G.ui_ResolverGroup:AddLabel'activate keybind (hold)':AddKeyPicker('ResolverKeybind',{
Default='None',
Mode='Hold',
Text='resolver activate',
NoUI=false,
Callback=function(br)

if br then
if not _G.resolverActive then
resolverActivate()
end
else
if _G.resolverActive then
resolverCleanup(true)
end
end
end
})

local br=false
local bs
local bt

local function _resolverHoldRecalcLoop()
if bs then bs:Disconnect();bs=nil end
bt=nil
bs=RunService.Heartbeat:Connect(function()
if not br then
bs:Disconnect();bs=nil;return
end
local bu=LocalPlayer.Character
local bv=bu and bu:FindFirstChild"HumanoidRootPart"
if not bv then return end
local bw=bv.Position
if bt==nil then bt=bw;return end
local bx=(bw-bt).Magnitude
if bx>(cfg.resolverradius*0.25)then
bt=bw

if _G.resolverActive then resolverCleanup(false)end
task.wait(0.05)
resolverActivate()
end
end)
end

UserInputService.InputBegan:Connect(function(bu,bv)
if bv then return end
if Options.ResolverKeybind and Options.ResolverKeybind.Value then
local bw=Options.ResolverKeybind.Value
if bu.UserInputType==Enum.UserInputType.Keyboard then
if bw~='None'and bu.KeyCode.Name==bw then
br=true
if not _G.resolverActive then resolverActivate()end
_resolverHoldRecalcLoop()
end
end
end

if Options.AutoResolverKeybind and Options.AutoResolverKeybind.Value then
local bw=Options.AutoResolverKeybind.Value
if bu.UserInputType==Enum.UserInputType.Keyboard then
if bw~='None'and bu.KeyCode.Name==bw then
local bx=not _G.resolver_auto
_G.resolver_auto=bx
if Toggles.ResolverAuto then pcall(function()Toggles.ResolverAuto:SetValue(bx)end)end
if bx then resolverAutoStart()else resolverAutoStop()end
end
end
end
end)
UserInputService.InputEnded:Connect(function(bu,bv)
if Options.ResolverKeybind and Options.ResolverKeybind.Value then
local bw=Options.ResolverKeybind.Value
if bu.UserInputType==Enum.UserInputType.Keyboard then
if bw~='None'and bu.KeyCode.Name==bw then
br=false
if _G.resolverActive then resolverCleanup(true)end
end
end
end
end)
