do
local bu=false
local bv=false
local bw=false
local bx={}
local by={}
local bz={}
local bA={}
local bB=120
local bC=5.0
local bD=60

local bE=game:GetService"Players"
local bF=game:GetService"RunService"
local bG=bE.LocalPlayer







local function _cd_markCheater(bH,bI)
if bx[bH]and bx[bH].cheater then return end
bx[bH]={cheater=true,reason=bI}
local bJ=os.date"[%H:%M:%S] "..bH.Name.." ("..tostring(bH.UserId)..") — "..bI
table.insert(by,bJ)
pcall(function()
if bv then
local bK=""
if isfile and isfile"seraph/debug/cheaters.txt"then
bK=readfile"seraph/debug/cheaters.txt"
end
if writefile then
writefile("seraph/debug/cheaters.txt",bK..bJ.."\n")
end
end
end)

if bw then
if not _G._cheater_priority_list then _G._cheater_priority_list={}end
_G._cheater_priority_list[bH.Name]=true
end
pcall(function()
if safeNotify then
safeNotify("cheater detected: "..bH.Name.." | "..bI,4)
end
end)
end


bF.Heartbeat:Connect(function(bH)
if not bu then return end
for bI,bJ in ipairs(bE:GetPlayers())do
if bJ==bG then continue end
local bK=bJ.Character
if not bK then continue end
local bL=bK:FindFirstChild"HumanoidRootPart"
local bM=bK:FindFirstChildWhichIsA"Humanoid"
if not bL or not bM then continue end

local bN=tick()
local bO=bL.Position
local bP=bz[bJ]

if bP then
local bQ=(bO-bP.pos).Magnitude
local bR=bN-bP.tick
if bR>0 then
local bS=bQ/bR
local bT=bM.SeatPart~=nil

if not bT and bS>bB then
if bQ>bD then
_cd_markCheater(bJ,"tp")
else
_cd_markCheater(bJ,"speed")
end
end
end
end


local bQ=bM.SeatPart~=nil
if bM.FloorMaterial==Enum.Material.Air and not bQ then
bA[bJ]=(bA[bJ]or 0)+bH
if bA[bJ]>bC then
_cd_markCheater(bJ,"fly")
end
else
bA[bJ]=0
end

bz[bJ]={pos=bO,tick=bN}
end
end)


bE.PlayerRemoving:Connect(function(bH)
bx[bH]=nil
bz[bH]=nil
bA[bH]=nil
if _G._cheater_priority_list then
_G._cheater_priority_list[bH.Name]=nil
end
end)


_G.cd_detected=bx
_G.cd_isCheater=function(bH)
local bI=bx[bH]
return bI and bI.cheater,bI and bI.reason or""
end


local bH=_G.getTarget
if bH then
_G.getTarget=function(...)
if not bw then return bH(...)end

local bI=game:GetService"Players".LocalPlayer
local bJ=game:GetService"Players"
local bK,bL=math.huge
for bM,bN in ipairs(bJ:GetPlayers())do
if bN==bI then continue end
if _G._cheater_priority_list and _G._cheater_priority_list[bN.Name]then
local bO=bN.Character
if bO then
local bP=bO:FindFirstChild"HumanoidRootPart"
local bQ=bI.Character and bI.Character:FindFirstChild"HumanoidRootPart"
if bP and bQ then
local bR=(bP.Position-bQ.Position).Magnitude
if bR<bK then bK=bR;bL=bN end
end
end
end
end
if bL then return bL end
return bH(...)
end
end


