_G._dynamic_fov_enabled=false
_G._dynamic_fov_base_fov=workspace.CurrentCamera and workspace.CurrentCamera.FieldOfView or 70
_G._dynamic_fov_base_radius=_G.mouse_aimbot_fov or 100
do
local bu=workspace.CurrentCamera
if bu then
_G._dynamic_fov_base_fov=bu.FieldOfView
end

_G._dynamic_fov_zoom_base=nil
game:GetService'RunService'.RenderStepped:Connect(function()
if not _G._dynamic_fov_enabled then
_G._dynamic_fov_zoom_base=nil
return
end
local bv=workspace.CurrentCamera
if not bv then return end
local bw=_G._dynamic_fov_base_fov or 70
local bx=_G._dynamic_fov_base_radius or(_G.mouse_aimbot_fov or 100)
local by=bv.FieldOfView


if _G.zoom_enabled and _G._zoom_active then

if not _G._dynamic_fov_zoom_base then
_G._dynamic_fov_zoom_base=by
end

local bz=_G._dynamic_fov_zoom_base/math.max(by,1)

_G.mouse_aimbot_fov=bx*bz

local bA=math.clamp(bw*bz,10,120)
if math.abs(bv.FieldOfView-bA)>0.5 then
bv.FieldOfView=bA
end
else
_G._dynamic_fov_zoom_base=nil

if math.abs(by-bw)>0.1 then
local bz=by/math.max(bw,1)
_G.mouse_aimbot_fov=bx*bz
_G._dynamic_fov_base_fov=by
end
end
end)
end

_G.mouse_fov_circle_enabled=false
_G._mouseFovCircle=nil
_G.mouse_fov_color=Color3.fromRGB(255,80,80)
_G.mouse_fov_color2=Color3.fromRGB(255,160,0)
_G.mouse_fov_filled=false
_G.mouse_fov_fill_trans=0.7
_G.mouse_fov_grad_enabled=false
_G.mouse_fov_outline_thick=1.5
_G.mouse_fov_outline_trans=0
_G.mouse_fov_spin=false
_G.mouse_fov_spin_speed=60
_G.mouse_fov_rot=0
_G.mouse_fov_anim="none"
_G.mouse_fov_anim_speed=1
_G._mouseFovAnimT=0
_G.mouse_fov_size_override=0
_G.mouse_fov_follow="mouse"

local function _makeMouseFovCircle()
if _G._mouseFovCircle then _G._mouseFovCircle:Destroy();_G._mouseFovCircle=nil end
_G._mouseFovGrad=nil;_G._mouseFovStroke=nil
if not _G.mouse_fov_circle_enabled then return end
local bu=_G._fovSGFrame and _G._fovSGFrame.Parent
if not bu then return end
local bv=Instance.new"Frame"
local bw=(_G.mouse_fov_size_override and _G.mouse_fov_size_override>0)and _G.mouse_fov_size_override or(_G.mouse_aimbot_fov or 100)
bv.Size=UDim2.new(0,bw*2,0,bw*2)
bv.AnchorPoint=Vector2.new(0.5,0.5)
bv.Position=UDim2.fromScale(0.5,0.5)
bv.BackgroundTransparency=_G.mouse_fov_filled and(_G.mouse_fov_fill_trans or 0.7)or 1
bv.BackgroundColor3=_G.mouse_fov_color
bv.BorderSizePixel=0
bv.ZIndex=6
bv.Parent=bu
Instance.new("UICorner",bv).CornerRadius=UDim.new(0.5,0)
local bx=Instance.new"UIStroke"
bx.Color=_G.mouse_fov_color
bx.Thickness=_G.mouse_fov_outline_thick or 1.5

bx.Enabled=true
bx.Transparency=(_G.mouse_fov_filled and not _G.mouse_fov_outline_when_filled)
and 1
or(_G.mouse_fov_outline_trans or 0)
bx.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
bx.Parent=bv
_G._mouseFovStroke=bx

local by=Instance.new"UIGradient"
by.Enabled=_G.mouse_fov_outline_grad or false
by.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,_G.mouse_fov_color),
ColorSequenceKeypoint.new(1,_G.mouse_fov_color2)
}
by.Parent=bx
_G._mouseFovOutlineGrad=by
if _G.mouse_fov_grad_enabled then
local bz=Instance.new"UIGradient"
bz.Color=ColorSequence.new{ColorSequenceKeypoint.new(0,_G.mouse_fov_color),ColorSequenceKeypoint.new(1,_G.mouse_fov_color2)}
bz.Parent=bv
_G._mouseFovFillGrad=bz
end
_G._mouseFovCircle=bv
end

RunService.RenderStepped:Connect(function(bu)
_G._mouseFovAnimT=(_G._mouseFovAnimT or 0)+bu*(_G.mouse_fov_anim_speed or 1)
if _G._mouseFovCircle then
local bv=(_G.mouse_fov_size_override and _G.mouse_fov_size_override>0)and _G.mouse_fov_size_override or(_G.mouse_aimbot_fov or 100)
local bw=1
local bx=_G.mouse_fov_anim or"none"
if bx=="pulse"then bw=1+0.1*math.sin(_G._mouseFovAnimT*4)
elseif bx=="breathe"then bw=1+0.06*math.sin(_G._mouseFovAnimT*1.8)
elseif bx=="expand"then bw=1+0.08*math.abs(math.sin(_G._mouseFovAnimT*2))
elseif bx=="shrink"then bw=1-0.08*math.abs(math.sin(_G._mouseFovAnimT*2))end
local by=bv*2*bw
_G._mouseFovCircle.Size=UDim2.new(0,by,0,by)
if _G.mouse_fov_spin then
_G.mouse_fov_rot=((_G.mouse_fov_rot or 0)+bu*(_G.mouse_fov_spin_speed or 60))%360
end
_G._mouseFovCircle.Rotation=_G.mouse_fov_rot or 0
local bz,bA=_getFovFollowPos(_G.mouse_fov_follow or"mouse",bv)
_G._mouseFovCircle.Position=UDim2.new(0,bz,0,bA)
_G._mouseFovCircle.BackgroundTransparency=_G.mouse_fov_filled and(_G.mouse_fov_fill_trans or 0.7)or 1
if _G.mouse_fov_grad_enabled then
if _G._mouseFovGrad then
_G._mouseFovGrad.Rotation=(_G.mouse_fov_rot or 0)
_G._mouseFovGrad.Color=ColorSequence.new{ColorSequenceKeypoint.new(0,_G.mouse_fov_color),ColorSequenceKeypoint.new(1,_G.mouse_fov_color2)}
end
if _G._mouseFovFillGrad then _G._mouseFovFillGrad.Rotation=(_G.mouse_fov_rot or 0)end
end
if _G._mouseFovStroke then
_G._mouseFovStroke.Color=_G.mouse_fov_color

local bB=_G.mouse_fov_filled and not _G.mouse_fov_outline_when_filled
_G._mouseFovStroke.Transparency=bB and 1 or(_G.mouse_fov_outline_trans or 0)
if _G._mouseFovOutlineGrad then
_G._mouseFovOutlineGrad.Enabled=_G.mouse_fov_outline_grad or false
_G._mouseFovOutlineGrad.Rotation=(_G.mouse_fov_rot or 0)
_G._mouseFovOutlineGrad.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,_G.mouse_fov_color),
ColorSequenceKeypoint.new(1,_G.mouse_fov_color2)
}
end
end
end
end)

