local function _makeTrigFovCircle()
if _G._trigFovCircle then _G._trigFovCircle:Destroy();_G._trigFovCircle=nil end
_G._trigFovGrad=nil;_G._trigFovStroke=nil
if not _G.trig_fov_circle_enabled then return end
local bw=_G._fovSGFrame and _G._fovSGFrame.Parent
if not bw then return end
local bx=Instance.new"Frame"
local by=(_G.trig_fov_size_override and _G.trig_fov_size_override>0)and _G.trig_fov_size_override or(cfg.triggerbot_fov or 20)
bx.Size=UDim2.new(0,by*2,0,by*2)
bx.AnchorPoint=Vector2.new(0.5,0.5)
bx.Position=UDim2.fromScale(0.5,0.5)
bx.BackgroundTransparency=_G.trig_fov_filled and(_G.trig_fov_fill_trans or 0.6)or 1
bx.BackgroundColor3=_G.trig_fov_color
bx.BorderSizePixel=0
bx.ZIndex=6
bx.Parent=bw
Instance.new("UICorner",bx).CornerRadius=UDim.new(0.5,0)
local bz=Instance.new"UIStroke"
bz.Color=_G.trig_fov_color
bz.Thickness=_G.trig_fov_outline_thickness
bz.Transparency=_G.trig_fov_outline_trans or 0
bz.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
bz.Parent=bx
_G._trigFovStroke=bz
if _G.trig_fov_grad_enabled then
local bA=Instance.new"UIGradient"
bA.Color=ColorSequence.new{ColorSequenceKeypoint.new(0,_G.trig_fov_color),ColorSequenceKeypoint.new(1,_G.trig_fov_color2)}
bA.Parent=bz
_G._trigFovGrad=bA
local bB=Instance.new"UIGradient"
bB.Color=bA.Color
bB.Parent=bx
_G._trigFovFillGrad=bB
end
_G._trigFovCircle=bx
end

local function _getFovFollowPos(bw,bx)
local by=workspace.CurrentCamera.ViewportSize
local bz,bA=by.X/2,by.Y/2
if bw=="mouse"then
local bB=UserInputService:GetMouseLocation()
return bB.X,bB.Y
elseif bw=="tool"then
local bB=LocalPlayer.Character
local bC=bB and bB:FindFirstChildOfClass"Tool"
local bD=bC and bC:FindFirstChild"Handle"
if bD then
local bE=workspace.CurrentCamera
local bF,bG=bE:WorldToViewportPoint(bD.Position)
if bG then return bF.X,bF.Y end
end
return bz,bA
elseif bw=="ragefov"then
if _G._rageFovPos then return _G._rageFovPos.X,_G._rageFovPos.Y end
return bz,bA
end
return bz,bA
end

RunService.RenderStepped:Connect(function(bw)
_G._trigFovAnimT=(_G._trigFovAnimT or 0)+bw*(_G.trig_fov_anim_speed or 1)
if _G._trigFovCircle then
local bx=(_G.trig_fov_size_override and _G.trig_fov_size_override>0)and _G.trig_fov_size_override or(cfg.triggerbot_fov or 20)
local by=1
local bz=_G.trig_fov_anim or"none"
if bz=="pulse"then by=1+0.1*math.sin(_G._trigFovAnimT*4)
elseif bz=="breathe"then by=1+0.06*math.sin(_G._trigFovAnimT*1.8)
elseif bz=="expand"then by=1+0.08*math.abs(math.sin(_G._trigFovAnimT*2))
elseif bz=="shrink"then by=1-0.08*math.abs(math.sin(_G._trigFovAnimT*2))end
local bA=bx*2*by
_G._trigFovCircle.Size=UDim2.new(0,bA,0,bA)
if _G.trig_fov_spin then
_G.trig_fov_rot=((_G.trig_fov_rot or 0)+bw*(_G.trig_fov_spin_speed or 60))%360
end
_G._trigFovCircle.Rotation=_G.trig_fov_rot or 0
local bB,bC=_getFovFollowPos(_G.trig_fov_follow or"center",bx)
_G._trigFovCircle.Position=UDim2.new(0,bB,0,bC)
_G._trigFovCircle.BackgroundTransparency=_G.trig_fov_filled and(_G.trig_fov_fill_trans or 0.6)or 1
if _G.trig_fov_grad_enabled then
if _G._trigFovGrad then
_G._trigFovGrad.Rotation=(_G.trig_fov_rot or 0)
_G._trigFovGrad.Color=ColorSequence.new{ColorSequenceKeypoint.new(0,_G.trig_fov_color),ColorSequenceKeypoint.new(1,_G.trig_fov_color2)}
end
if _G._trigFovFillGrad then
_G._trigFovFillGrad.Rotation=(_G.trig_fov_rot or 0)
end
end
if _G._trigFovStroke then
_G._trigFovStroke.Color=_G.trig_fov_color
_G._trigFovStroke.Transparency=_G.trig_fov_outline_trans or 0
end
end
_G._legitFovAnimT=(_G._legitFovAnimT or 0)+bw*(_G.legit_fov_anim_speed or 1)
if _G._legitFovCircle then
local bx=(_G.legit_fov_size_override and _G.legit_fov_size_override>0)and _G.legit_fov_size_override or cfg.legit_fov
local by=1
local bz=_G.legit_fov_anim or"none"
if bz=="pulse"then by=1+0.1*math.sin(_G._legitFovAnimT*4)
elseif bz=="breathe"then by=1+0.06*math.sin(_G._legitFovAnimT*1.8)
elseif bz=="expand"then by=1+0.08*math.abs(math.sin(_G._legitFovAnimT*2))
elseif bz=="shrink"then by=1-0.08*math.abs(math.sin(_G._legitFovAnimT*2))end
local bA=bx*by*2
_G._legitFovCircle.Size=UDim2.new(0,bA,0,bA)
if _G.legit_fov_spin then
_G.legit_fov_rot=((_G.legit_fov_rot or 0)+bw*(_G.legit_fov_spin_speed or 60))%360
end
_G._legitFovCircle.Rotation=_G.legit_fov_rot or 0
local bB,bC=_getFovFollowPos(_G.legit_fov_follow or"center",bx)
_G._legitFovCircle.Position=UDim2.new(0,bB,0,bC)
_G._legitFovCircle.BackgroundTransparency=_G.legit_fov_filled and(_G.legit_fov_fill_trans or 0.6)or 1
if _G.legit_fov_grad_enabled then
if _G._legitFovGrad then
_G._legitFovGrad.Rotation=(_G.legit_fov_rot or 0)
_G._legitFovGrad.Color=ColorSequence.new{ColorSequenceKeypoint.new(0,_G.legit_fov_color),ColorSequenceKeypoint.new(1,_G.legit_fov_color2)}
end
if _G._legitFovFillGrad then
_G._legitFovFillGrad.Rotation=(_G.legit_fov_rot or 0)
end
end
if _G._legitFovStroke then
_G._legitFovStroke.Color=_G.legit_fov_color
_G._legitFovStroke.Transparency=_G.legit_fov_outline_trans or 0
end
end
end)

