local function _applySkyPreset(bF)
if not bF then return end

local bG=game:GetService"Lighting"

local bH=bG:FindFirstChild"Sky"


local function _sid(bI)
if not bI then return nil end

bI=tostring(bI)

local bJ=bI:match"(%d+)"

if bJ then
return"rbxassetid://"..bJ
end

return bI
end

bH.SkyboxBk=_sid(bF.SkyboxBk)
bH.SkyboxDn=_sid(bF.SkyboxDn)
bH.SkyboxFt=_sid(bF.SkyboxFt)
bH.SkyboxLf=_sid(bF.SkyboxLf)
bH.SkyboxRt=_sid(bF.SkyboxRt)
bH.SkyboxUp=_sid(bF.SkyboxUp)

bH.StarCount=bF.StarCount or 3000
bH.SunAngularSize=bF.SunAngularSize or 21
bH.MoonAngularSize=bF.MoonAngularSize or 11

if bF.MoonTextureId and bF.MoonTextureId~=""then
bH.MoonTextureId=bF.MoonTextureId
end

if bF.SunTextureId and bF.SunTextureId~=""then
bH.SunTextureId=bF.SunTextureId
end

bH.Parent=bG
end
local bF={}
for bG in pairs(bE)do
table.insert(bF,bG)
end
table.sort(bF)

_G.sky_preset_active=false

_G.ui_VisualsGroup:AddDropdown('SkyPreset',{
Values=bF,
Default=1,
Multi=false,
Text='sky preset',
Tooltip='quick sky presets - applies immediately',

Callback=function(bG)
local bH=bE[bG]
if not bH then
return
end

_G.sky_preset_active=true

_applySkyPreset(bH)

_G.sky_enabled=true

if Toggles.SkyEnabled and not Toggles.SkyEnabled.Value then
Toggles.SkyEnabled:SetValue(true)
end
end
})
