task.spawn(function()
local bH=game:GetService'UserInputService'
local function _getZoomKey()

local bI,bJ=pcall(function()
return Options and Options.ZoomKeybind and Options.ZoomKeybind.Value
end)
if not bI or not bJ then return nil end

if typeof(bJ)=='EnumItem'then return bJ end
local bK=tostring(bJ):match'%.(%w+)$'or tostring(bJ)
return Enum.KeyCode[bK]
end
bH.InputBegan:Connect(function(bI,bJ)
if bJ or not _G.zoom_enabled then return end
local bK=_getZoomKey()
if bK and bI.KeyCode==bK then
_G._zoom_active=true
_G._zoom_target=_G.zoom_fov_in or 30
end
end)
bH.InputEnded:Connect(function(bI)
if not _G.zoom_enabled then return end
local bJ=_getZoomKey()
if bJ and bI.KeyCode==bJ then
_G._zoom_active=false
_G._zoom_target=_G.zoom_fov_out or 70
end
end)
end)

local bH=0
RunService.RenderStepped:Connect(function(bI)
if not _G.zoom_enabled then

_G._zoom_current=_G.zoom_fov_out or 70
_G._zoom_target=_G.zoom_fov_out or 70
_G._zoom_active=false
bH=0
return
end
local bJ=workspace.CurrentCamera
if not bJ then return end
local bK=_G._zoom_current
local bL=_G._zoom_target
local bM=_G.zoom_speed or 0.15
local bN=_G.zoom_transition or'lerp'
local bO=bK
if bN=='instant'then
bO=bL
elseif bN=='lerp'then
bO=bK+(bL-bK)*math.min(bM*60*bI,1)
elseif bN=='ease'then
local bP=math.min(bM*60*bI,1)
bO=bK+(bL-bK)*(bP*bP*(3-2*bP))
elseif bN=='linear'then
local bP=math.min(bM*200*bI,math.abs(bL-bK))
bO=bK+(bL>bK and bP or-bP)
elseif bN=='spring'then
local bP=(bL-bK)*(bM*800)-bH*(bM*60)
bH=bH+bP*bI
bO=bK+bH*bI
end
bO=math.clamp(bO,1,120)
_G._zoom_current=bO
bJ.FieldOfView=bO
end)



