local function getClosestPlayer()
local bI=LocalPlayer.Character and LocalPlayer.Character:FindFirstChild"HumanoidRootPart"
if not bI then return nil end
local bJ,bK=math.huge
for bL,bM in ipairs(f:GetPlayers())do
if bM~=LocalPlayer and bM.Character and bM.Character:FindFirstChild"HumanoidRootPart"then
local bN=(bM.Character.HumanoidRootPart.Position-bI.Position).Magnitude
if bN<bJ then
bJ=bN
bK=bM
end
end
end
return bK
end




_G.carfling_team_filter={}
local function _cf_resolveTarget()
if _G.carfling_target and _G.carfling_target.Parent then
return _G.carfling_target
end

if next(_G.carfling_team_filter)then
local bI,bJ=math.huge
local bK=LocalPlayer.Character
local bL=bK and bK:FindFirstChild'HumanoidRootPart'
if bL then
for bM,bN in ipairs(f:GetPlayers())do
if bN==LocalPlayer then continue end
local bO=bN.Team and bN.Team.Name or''
if not _G.carfling_team_filter[bO]then continue end
local bP=bN.Character
local bQ=bP and bP:FindFirstChild'HumanoidRootPart'
local bR=bP and bP:FindFirstChildOfClass'Humanoid'
if bQ and bR and bR.Health>0 then
local bS=(bL.Position-bQ.Position).Magnitude
if bS<bI then bI=bS;bJ=bN end
end
end
end
return bJ
end
return getClosestPlayer()
end



local function _cf_getCarNames()
local bI={}
if _G._carfling_container then
for bJ,bK in ipairs(_G._carfling_container:GetChildren())do
if(bK:IsA"Model"or bK:IsA"Folder")and bK:FindFirstChild"Wheels"then
table.insert(bI,bK.Name)
end
end
end
return bI
end


local function _cf_getPlayerNames()
