for bJ,bK in ipairs(f:GetPlayers())do
if bK~=LocalPlayer then table.insert(bI,bK.Name)end
end
return bI
end



local function _cf_getNearestCar()
if not _G._carfling_container then return nil end
local bI
if _G.carfling_nearest_ref=='localplayer'then
local bJ=LocalPlayer.Character
bI=bJ and bJ:FindFirstChild"HumanoidRootPart"
else
local bJ=_cf_resolveTarget()
bI=bJ and bJ.Character and bJ.Character:FindFirstChild"HumanoidRootPart"
if not bI then
local bK=LocalPlayer.Character
bI=bK and bK:FindFirstChild"HumanoidRootPart"
end
end
if not bI then return nil end
local bJ,bK=math.huge
for bL,bM in ipairs(_G._carfling_container:GetChildren())do
if(bM:IsA"Model"or bM:IsA"Folder")and bM:FindFirstChild"Wheels"then
local bN,bO=pcall(function()
if bM:IsA"Model"then return bM:GetPivot().Position end
for bN,bO in ipairs(bM:GetDescendants())do
if bO:IsA"BasePart"then return bO.Position end
end
return nil
end)
if bN and bO then
local bP=(bO-bI.Position).Magnitude
if bP<bJ then bJ=bP;bK=bM end
end
end
end
return bK
end




local function _cf_getOwnCar()
local bI=LocalPlayer.Character
local bJ=bI and bI:FindFirstChildOfClass"Humanoid"
local bK=bJ and bJ.SeatPart
if not bK then return nil end
local bL=bK
while bL and bL~=workspace do
if(bL:IsA"Model"or bL:IsA"Folder")and bL:FindFirstChild"Wheels"then
return bL
end
bL=bL.Parent
end
return nil
end




local function _cf_getWheelsContainer(bI)
