local function _cf_destroyAllConstraints(bP,bQ)
local bR={}
for bS,bT in ipairs(bQ:GetDescendants())do
if bT:IsA"BasePart"then bR[bT]=true end
end
for bS,bT in ipairs(bP:GetDescendants())do
local bU=false



if bT:IsA"Weld"or bT:IsA"Motor6D"or bT:IsA"WeldConstraint"then
local bV,bW,bX=pcall(function()return bT.Part0,bT.Part1 end)
if bV then
if bW and bR[bW]then bU=true end
if bX and bR[bX]then bU=true end
end


elseif bT:IsA"Constraint"then
local bV,bW,bX=pcall(function()return bT.Attachment0,bT.Attachment1 end)
if bV then
if bW and bW.Parent and bR[bW.Parent]then bU=true end
if bX and bX.Parent and bR[bX.Parent]then bU=true end
end
end
if bU then pcall(function()bT:Destroy()end)end
end
end

local function _cf_collectChassisParts(bP,bQ)
local bR={}
for bS,bT in ipairs(bP:GetDescendants())do
if bT:IsA"BasePart"and bT.Parent~=bQ then
table.insert(bR,bT)
end
end
return bR
end


local function _cf_push_DestroyConstraints(bP,bQ)
_cf_destroyAllConstraints(bP,bQ)
end

local function _cf_push_CollisionGroup(bP,bQ)
local bR=game:GetService"PhysicsService"
local bS="CarFlingWheels"
pcall(function()bR:RegisterCollisionGroup(bS)end)
pcall(function()bR:CollisionGroupSetCollidable(bS,"Default",false)end)
for bT,bU in ipairs(bQ:GetDescendants())do
if bU:IsA"BasePart"then
pcall(function()bU.CollisionGroup=bS end)
end
end
end

local function _cf_push_AnchorChassis(bP,bQ)
for bR,bS in ipairs(_cf_collectChassisParts(bP,bQ))do
pcall(function()bS.Anchored=true end)
end
end

local function _cf_push_ZeroVelocitySetup(bP,bQ)
_G._carfling_chassis_parts=_cf_collectChassisParts(bP,bQ)
end

local function _cf_push_MasslessWheels(bP,bQ)
for bR,bS in ipairs(bQ:GetDescendants())do
if bS:IsA"BasePart"then
pcall(function()
bS.Massless=true
bS.CustomPhysicalProperties=PhysicalProperties.new(0.01,0.3,0.3,1,1)
end)
end
end
end





local function _cf_push_LockChassisVF(bP,bQ)
local bR={}
for bS,bT in ipairs(_cf_collectChassisParts(bP,bQ))do
bR[bT]=bT.CFrame
end
_G._carfling_chassis_locks=bR
end

local function _cf_push_WeldToAnchor(bP,bQ)
local bR
if bP:IsA"Model"then
local bS,bT=pcall(function()return bP:GetPivot()end)
if bS then bR=bT end
end
if not bR then
for bS,bT in ipairs(bP:GetDescendants())do
if bT:IsA"BasePart"then bR=bT.CFrame;break end
end
end
if not bR then return end

local bS=Instance.new"Part"
bS.Name="CarFlingAnchor"
bS.Size=Vector3.new(1,1,1)
bS.Transparency=1
bS.CanCollide=false
bS.Anchored=true
bS.CFrame=bR
bS.Parent=workspace

for bT,bU in ipairs(_cf_collectChassisParts(bP,bQ))do
local bV=Instance.new"WeldConstraint"
bV.Part0=bS
bV.Part1=bU
bV.Parent=bS
end
_G._carfling_anchor_part=bS
end

local function _cf_push_NetworkOwnerLock(bP,bQ)
for bR,bS in ipairs(_cf_collectChassisParts(bP,bQ))do
pcall(function()bS:SetNetworkOwner(nil)end)
end
end

local function _cf_push_RelocateChassis(bP,bQ)
local bR=Vector3.new(0,500,0)
for bS,bT in ipairs(_cf_collectChassisParts(bP,bQ))do
pcall(function()
bT.CFrame=bT.CFrame+bR
bT.Anchored=true
end)
end
end

local bP={
['destroy all constraints']=_cf_push_DestroyConstraints,
['collision group']=_cf_push_CollisionGroup,
['anchor chassis']=_cf_push_AnchorChassis,
['zero chassis velocity']=_cf_push_ZeroVelocitySetup,
['massless wheels']=_cf_push_MasslessWheels,
['lock chassis (vehicle fly style)']=_cf_push_LockChassisVF,
['weld chassis to anchor']=_cf_push_WeldToAnchor,
['network ownership lock']=_cf_push_NetworkOwnerLock,
['relocate chassis away']=_cf_push_RelocateChassis,
}





local function _cf_setupCar()
if not _G._carfling_container then
safeNotify("carfling: CarContainer not found",2)
return nil
end



_G._carfling_chassis_parts=nil
_G._carfling_chassis_locks=nil
if _G._carfling_anchor_part then
pcall(function()_G._carfling_anchor_part:Destroy()end)
_G._carfling_anchor_part=nil
end

local bQ
if _G.carfling_use_own_car then
bQ=_cf_getOwnCar()
if not bQ then
safeNotify("carfling: you are not seated in a car",2)
return nil
end
elseif _G.carfling_use_nearest then
bQ=_cf_getNearestCar()
elseif _G.carfling_use_dropdown and _G.carfling_selected_car then
bQ=_G._carfling_container:FindFirstChild(_G.carfling_selected_car)
end
if not bQ then
safeNotify("carfling: no car resolved (pick a car, or enable nearest/own car)",2)
return nil
end

local bR=_cf_getWheelsContainer(bQ)
if not bR then
safeNotify("carfling: "..bQ.Name.." has no Wheels folder",2)
return nil
end




_cf_destroyAllConstraints(bQ,bR)


for bS,bT in ipairs(bQ:GetDescendants())do
if bT:IsA"BasePart"and bT.Parent~=bR then
bT.CanCollide=false
end
end


if _G.carfling_disable_wheel_collision then
for bS,bT in ipairs(bR:GetDescendants())do
if bT:IsA"BasePart"then bT.CanCollide=false end
end
end


if _G.carfling_prevent_push then
local bS=bP[_G.carfling_push_method]
if bS then pcall(bS,bQ,bR)end
end

return bR,bQ
end








