local bQ=150


local function _cf_getAllTargets()
local bR={}
for bS,bT in ipairs(f:GetPlayers())do
if bT~=LocalPlayer and bT.Character and bT.Character:FindFirstChild"HumanoidRootPart"then
table.insert(bR,bT)
