local function _cf_rebuildAffectAllSlots()
_G._carfling_targetSlots={}
_G._carfling_targetQueue={}

local bR=_G._carfling_wheels
if not bR then return end

local bS={}
for bT,bU in ipairs(bR:GetChildren())do
if bU:IsA"BasePart"then table.insert(bS,bU)end
end
if#bS==0 then return end

local bT=math.max(1,_G.carfling_wheels_per_target or 1)
local bU=_cf_getAllTargets()


for bV=#bU,2,-1 do
local bW=math.random(bV)
bU[bV],bU[bW]=bU[bW],bU[bV]
end

local bV=1
local bW={}
for bX,bY in ipairs(bU)do
if bV>#bS then break end
local bZ={}
for b_=1,bT do
if bV>#bS then break end
table.insert(bZ,bS[bV])
bV=bV+1
end
if#bZ>0 then
table.insert(_G._carfling_targetSlots,{player=bY,wheels=bZ})
bW[bY]=true
end
end

for bX,bY in ipairs(bU)do
if not bW[bY]then table.insert(_G._carfling_targetQueue,bY)end
end
end



local function _cf_slotIsDone(bR)
local bS=bR.player
if not bS or not bS.Parent then return true end
local bT=bS.Character
if not bT then return true end
local bU=bT:FindFirstChildOfClass"Humanoid"
if not bU or bU.Health<=0 then return true end
local bV=bT:FindFirstChild"HumanoidRootPart"
if not bV then return true end
if bV.AssemblyLinearVelocity.Magnitude>bQ then return true end
return false
end





