local b8=workspace.CurrentCamera
if not b8 then return end
local b9=_G.clickfling_speed or 40
local ca=Vector3.zero

if bV:IsKeyDown(Enum.KeyCode.W)then ca=ca+bX.LookVector end
if bV:IsKeyDown(Enum.KeyCode.S)then ca=ca-bX.LookVector end
if bV:IsKeyDown(Enum.KeyCode.A)then ca=ca-bX.RightVector end
if bV:IsKeyDown(Enum.KeyCode.D)then ca=ca+bX.RightVector end
if bV:IsKeyDown(Enum.KeyCode.E)then ca=ca+Vector3.new(0,1,0)end
if bV:IsKeyDown(Enum.KeyCode.Q)then ca=ca-Vector3.new(0,1,0)end

local cb=bV:GetGamepadState(Enum.UserInputType.Gamepad1)
for cc,cd in ipairs(cb)do
if cd.KeyCode==Enum.KeyCode.Thumbstick1 then
