local bV=_G._carfling_wheels
if not bV then return end
local bW=_G._clickfling_target
local bX=_G.clickfling_lerp or 0.2
local bY=_G.clickfling_force or 5000
for bZ,b_ in ipairs(bV:GetChildren())do
if b_:IsA'BasePart'then

b_.CFrame=b_.CFrame:Lerp(CFrame.new(bW),bX)

local b0=(bW-b_.Position)
if b0.Magnitude>0 then
b_.AssemblyLinearVelocity=b0.Unit*bY
end
end
end

if _G.clickfling_lock_chassis and _G._carfling_chassis_locks then
for bZ,b_ in pairs(_G._carfling_chassis_locks)do
if bZ and bZ.Parent then
bZ.AssemblyLinearVelocity=Vector3.zero
bZ.AssemblyAngularVelocity=Vector3.zero
bZ.CFrame=b_
end
end
end
end)




