local function _ma_getStatus(b_)
local b0=b_:FindFirstChildOfClass'Humanoid'
if not b0 then return'Regular'end
local b1=b0.DisplayName
if string.sub(b1,1,4)=='\xF0\x9F\x94\x97'then return'Arrestable'
elseif string.sub(b1,1,4)=='\xF0\x9F\x92\xA2'then return'Aggressive'end
return'Regular'
end

local function _ma_shouldTarget(b_)
if _G.melee_aura_whitelist[b_.Name]then return false end
if _G.melee_aura_friend_check and _G._friendsCache and _G._friendsCache[b_.Name]then return false end
local b0=b_.Team and b_.Team.Name or''
if next(_G.melee_aura_teams)and not _G.melee_aura_teams[b0]then return false end
if b0=='Inmates'and next(_G.melee_aura_inmate_types)then
local b1=b_.Character
if b1 and not _G.melee_aura_inmate_types[_ma_getStatus(b1)]then return false end
end
return true
end

