RunService.Heartbeat:Connect(function(b2)
if not _G.melee_aura_enabled then
for b3,b4 in ipairs(bX)do b4.Visible=false end
for b3,b4 in ipairs(bY)do b4.Visible=false end
bZ.Visible=false
return
end
local b3=LocalPlayer.Character
if not b3 then return end
local b4=b3:FindFirstChild'HumanoidRootPart'
if not b4 then return end

_G._melee_aura_pulse_t=(_G._melee_aura_pulse_t or 0)+b2
local b5=_G.melee_aura_radius
if _G.melee_aura_pulse then
local b6=math.sin(_G._melee_aura_pulse_t*_G.melee_aura_pulse_speed)*0.15
b5=b5*(1+b6)
end

local b6=workspace.CurrentCamera
local b7=b4.Position.Y-3
local b8=Vector3.new(b4.Position.X,b7,b4.Position.Z)


if _G.melee_aura_grad_anim then
_G._melee_aura_grad_offset=(_G._melee_aura_grad_offset or 0)+b2*_G.melee_aura_grad_speed
end


local function _ma_gradColor(b9)
local ca=_G.melee_aura_grad_anim and(_G._melee_aura_grad_offset%1)or 0
local cb=(b9+ca)%1
if cb<0.5 then
return _G.melee_aura_grad_color1:Lerp(_G.melee_aura_grad_color2,cb*2)
else
return _G.melee_aura_grad_color2:Lerp(_G.melee_aura_grad_color3,(cb-0.5)*2)
end
end


local b9={}
local ca={}
local cb=(2*math.pi)/bW
for cc=1,bW do
local cd=cb*cc
local ce=b8+Vector3.new(math.cos(cd)*b5,0,math.sin(cd)*b5)
local cf,cg=b6:WorldToViewportPoint(ce)
b9[cc]=Vector2.new(cf.X,cf.Y)
ca[cc]=cg
end
Vector2.new(b6.ViewportSize.X/2,b6.ViewportSize.Y/2)
local cc=b6:WorldToViewportPoint(b8)
local cd=Vector2.new(cc.X,cc.Y)

if _G.melee_aura_show_radius then
for ce=1,bW do
local cf=(ce%bW)+1
local cg=bX[ce]
if ca[ce]and ca[cf]then
cg.From,cg.To,cg.Visible=b9[ce],b9[cf],true
if _G.melee_aura_grad_enabled then
cg.Color=_ma_gradColor(ce/bW)
else
cg.Color=_G.melee_aura_grad_color1
end
else
cg.Visible=false
end
end
else
for ce,cf in ipairs(bX)do cf.Visible=false end
end


if _G.melee_aura_filled then
for ce=1,bW do
local cf=(ce%bW)+1
local cg=bY[ce]
if ca[ce]and ca[cf]then
cg.PointA=cd
cg.PointB=b9[ce]
cg.PointC=b9[cf]
cg.Transparency=_G.melee_aura_fill_transp
cg.Visible=true
if _G.melee_aura_fill_grad and _G.melee_aura_grad_enabled then
cg.Color=_ma_gradColor(ce/bW)
else
cg.Color=_G.melee_aura_grad_color1
end
else
cg.Visible=false
end
end
else
for ce,cf in ipairs(bY)do cf.Visible=false end
end


local ce,cf,cg=b5
for ch,ci in ipairs(bV:GetPlayers())do
if ci==LocalPlayer then continue end
if not _ma_shouldTarget(ci)then continue end
local cj=ci.Character
if not cj then continue end
local ck=cj:FindFirstChildOfClass'Humanoid'
if not ck or ck.Health<=0 then continue end
local cl=cj:FindFirstChild'HumanoidRootPart'
if not cl then continue end
local cm=(b4.Position-cl.Position).Magnitude
if cm<ce then
ce,cf,cg=cm,cl,ci
end
end

if cf and bU then
pcall(function()bU:FireServer(cg,1,1)end)

if _G.melee_aura_hit_notif and _G.hit_notif_enabled~=false then
local ch=cg.Character and cg.Character:FindFirstChildOfClass'Humanoid'
if ch then
local ci=_G._ma_hit_health[cg]
local cj=ch.Health
if ci and cj<ci and cj>0 then
local ck=math.floor(ci-cj)
local cl=math.floor(ce)
local cm=_G.hit_notif_format or'hit {USER} ({ZONE}) {DAMAGE} dmg · {TOOL} · {DISTANCE}m'
local cn=cm
:gsub('{USER}',cg.Name)
:gsub('{DISPLAYNAME}',cg.DisplayName or cg.Name)
:gsub('{ZONE}','body')
:gsub('{DAMAGE}',tostring(ck))
:gsub('{TOOL}','melee')
:gsub('{DISTANCE}',tostring(cl))
safeNotify(cn,1.5)
if cfg.hitsound then
if cfg.hitsound_lib_enabled and cfg.hitsound_lib_picks and#cfg.hitsound_lib_picks>0 then
_G._playLibSoundMulti(cfg.hitsound_lib_picks,cfg.hitsoundvolume)
else
local co=Instance.new('Sound',workspace)
co.SoundId=cfg.hitsoundid
co.Volume=cfg.hitsoundvolume
co:Play()
game:GetService'Debris':AddItem(co,2)
end
end
end
if ci and cj<=0 and ci>0 then
if _G.melee_aura_kill_notif and _G.kill_notif_enabled~=false then
local ck=math.floor(ce)
local cl=_G.kill_notif_format or'killed {USER} with {TOOL} from {DISTANCE}m'
local cm=cl
:gsub('{USER}',cg.Name)
:gsub('{DISPLAYNAME}',cg.DisplayName or cg.Name)
:gsub('{TOOL}','melee')
:gsub('{DISTANCE}',tostring(ck))
safeNotify(cm,3)
end
end
_G._ma_hit_health[cg]=cj
end
end

if _G.melee_aura_show_target then
local ch=cf.Position.Y-3
local ci=Vector3.new(b4.Position.X,b7,b4.Position.Z)
local cj=Vector3.new(cf.Position.X,ch,cf.Position.Z)
local ck,cl=b6:WorldToViewportPoint(ci)
local cm,cn=b6:WorldToViewportPoint(cj)
if cl and cn then
bZ.From=Vector2.new(ck.X,ck.Y)
bZ.To=Vector2.new(cm.X,cm.Y)
bZ.Transparency=_G.melee_aura_tgt_transp or 0
if _G.melee_aura_tgt_grad then
_G._ma_tgt_grad_t=(_G._ma_tgt_grad_t or 0)+b2*(_G.melee_aura_tgt_grad_spd or 1)
local co=_G.melee_aura_tgt_color or Color3.fromRGB(50,150,255)
local cp=_G.melee_aura_tgt_grad_c2 or Color3.fromRGB(255,80,80)
if _G.melee_aura_tgt_grad_anim then
bZ.Color=co:Lerp(cp,0.5+0.5*math.sin(_G._ma_tgt_grad_t*math.pi*2))
else
bZ.Color=co:Lerp(cp,0.5)
end
else
bZ.Color=_G.melee_aura_tgt_color or Color3.fromRGB(50,150,255)
end
bZ.Visible=true
else
bZ.Visible=false
end
else
bZ.Visible=false
end
else
bZ.Visible=false
end
end)

_G._antisit_enabled=false
_G._antisit_conn=nil
local function _antisit_apply()
if _G._antisit_conn then _G._antisit_conn:Disconnect();_G._antisit_conn=nil end
if not _G._antisit_enabled then return end
local function _unseat_char(b2)
if not b2 then return end
local b3=b2:FindFirstChildOfClass'Humanoid'
if b3 and b3.SeatPart then
pcall(function()b3.Sit=false end)
pcall(function()
for b4,b5 in ipairs(game:GetService'Workspace':GetDescendants())do
if(b5:IsA'Seat'or b5:IsA'VehicleSeat')and b5.Occupant==b3 then
b5:Destroy()
end
end
end)
end
end
_G._antisit_conn=game:GetService'RunService'.Heartbeat:Connect(function()
if not _G._antisit_enabled then
_G._antisit_conn:Disconnect();_G._antisit_conn=nil;return
end
local b2=game:GetService'Players'.LocalPlayer.Character
_unseat_char(b2)
end)
end

_G._antifling_enabled=false
_G._antifling_conn=nil
local b2={}
local function _antifling_apply()
if _G._antifling_conn then _G._antifling_conn:Disconnect();_G._antifling_conn=nil end
if not _G._antifling_enabled then
for b3,b4 in pairs(b2)do
pcall(function()
if b3 and b3.Parent then
b3.CustomPhysicalProperties=b4.cpp
b3.Velocity=Vector3.zero
b3.RotVelocity=Vector3.zero
end
end)
end
b2={}
return
end
_G._antifling_conn=game:GetService'RunService'.Heartbeat:Connect(function()
if not _G._antifling_enabled then
_G._antifling_conn:Disconnect();_G._antifling_conn=nil;return
end
local b3=game:GetService'Players'.LocalPlayer.Character
if not b3 then return end
for b4,b5 in ipairs(b3:GetDescendants())do
if b5:IsA'BasePart'and b5.CanCollide then
local b6=b5.Velocity
local b7=200
if b6.Magnitude>b7 then
pcall(function()
b5.Velocity=Vector3.zero
b5.RotVelocity=Vector3.zero
b5.AssemblyLinearVelocity=Vector3.zero
b5.AssemblyAngularVelocity=Vector3.zero
end)
end
end
end
for b4,b5 in ipairs(game:GetService'Players':GetPlayers())do
if b5==game:GetService'Players'.LocalPlayer then continue end
local b6=b5.Character
if not b6 then continue end
for b7,b8 in ipairs(b6:GetDescendants())do
if b8:IsA'BasePart'and b8.CanCollide and b8.Velocity.Magnitude>300 then
pcall(function()
b8.Velocity=Vector3.zero
b8.RotVelocity=Vector3.zero
b8.AssemblyLinearVelocity=Vector3.zero
b8.AssemblyAngularVelocity=Vector3.zero
end)
end
end
end
end)
end



