local function getSwitcherTools()
local ca={}
local cb={}
local cc=LocalPlayer:FindFirstChild"Backpack"
local cd=LocalPlayer.Character
for ce,cf in ipairs{cc,cd}do
if cf then
for cg,ch in ipairs(cf:GetChildren())do
if ch:IsA"Tool"and not cb[ch.Name]then
cb[ch.Name]=true
table.insert(ca,ch.Name)
end
end
end
end
return ca
end

local ca

ca=_G.ui_miscGroup:AddDropdown('SwitcherTools',{
Values=getSwitcherTools(),
Default={},
Text='tools to switch',
Tooltip='select multiple tools to cycle',
Multi=true,
Callback=function(cb)

local cc={}
for cd,ce in pairs(cb)do
if ce then table.insert(cc,cd)end
end
table.sort(cc)
_G.switcher_tools=cc
end
})

_G.ui_miscGroup:AddButton{
Text='refresh tool list',
Func=function()
local cb=getSwitcherTools()

pcall(function()ca:SetValues(cb)end)
end
}

_G.ui_miscGroup:AddSlider('SwitcherSpeed',{
Text='switch interval (s)',Default=0.5,Min=0,Max=5,Rounding=5,
Callback=function(cb)_G.switcher_speed=cb end
})

local function _switcherStart()
if _G._switcher_conn then _G._switcher_conn:Disconnect()end
_G._switcher_idx=1
local cb=0
_G._switcher_conn=RunService.Heartbeat:Connect(function()
if not _G.switcher_enabled then
_G._switcher_conn:Disconnect();_G._switcher_conn=nil
return
end
local cc=_G.switcher_tools
if type(cc)~="table"or#cc<2 then return end
local cd=tick()
if cd-cb<(_G.switcher_speed or 0.5)then return end
cb=cd
_G._switcher_idx=(_G._switcher_idx or 1)
local ce=cc[_G._switcher_idx]
_G._switcher_idx=(_G._switcher_idx%#cc)+1
local cf=LocalPlayer.Character
if not cf then return end
local cg=cf:FindFirstChildOfClass"Humanoid"
if not cg then return end
local ch=LocalPlayer:FindFirstChild"Backpack"
local ci=(ch and ch:FindFirstChild(ce))or cf:FindFirstChild(ce)
if ci and ci:IsA"Tool"then
pcall(function()cg:EquipTool(ci)end)
end
end)
end

local function _switcherStop()
_G.switcher_enabled=false
if _G._switcher_conn then _G._switcher_conn:Disconnect();_G._switcher_conn=nil end
end

_G.ui_miscGroup:AddToggle('SwitcherEnabled',{
Text='enable tool switcher',Default=false,
Callback=function(cb)
_G.switcher_enabled=cb
if cb then _switcherStart()else _switcherStop()end
end
})

