_G._autogetguns_loop=nil

local cb={"__FAL","M4A1","Revolver","AK-47","M700","MP5","Remington 870"}











local function _getGiverClickPart(cc)
local cd=LocalPlayer.Character
local ce=cd and cd:FindFirstChild"HumanoidRootPart"
local cf=ce and ce.Position or Vector3.new(0,0,0)

local cg=cc:GetChildren()
if#cg==0 then return cc end

local ch,ci=math.huge
for cj,ck in ipairs(cg)do
if ck:IsA"BasePart"or ck:IsA"MeshPart"or ck:IsA"Model"then
local cl=ck:IsA"Model"and ck.PrimaryPart or ck
if cl and cl:IsA"BasePart"then
local cm=(cl.Position-cf).Magnitude
if cm<ch then ch=cm;ci=ck end
end
end
end
return ci or cg[1]
end

local function _invokeGetGun(cc)
local cd,ce=pcall(function()
local cd=game:GetService"ReplicatedStorage":WaitForChild("Remotes",3):WaitForChild("InteractWithItem",3)
local ce=workspace:FindFirstChild"Prison_ITEMS"
if not ce then error"no Prison_ITEMS"end
local cf=ce:FindFirstChild"giver"
if not cf then error"no giver"end
local cg=cf:FindFirstChild(cc)
if not cg then error("no giver model: "..cc)end
local ch=_getGiverClickPart(cg)
if not ch then error"no click part"end
cd:InvokeServer(ch)
end)
if not cd and _G.autogetguns_notify then
safeNotify("get gun fail: "..cc.." - "..tostring(ce),2)
end
end

local cc
local cd={}

local function _startBackpackWatch()
if cc then cc:Disconnect()end
local ce=LocalPlayer:FindFirstChild"Backpack"
if not ce then return end
cc=ce.ChildAdded:Connect(function(cf)
if not(_G.autogetguns_notify and cf:IsA"Tool")then return end
local cg=cf.Name

local ch=_G.autogetguns_selected or{}
local ci=false
for cj,ck in ipairs(ch)do
if ck==cg then ci=true;break end
end
if not ci then return end

if cd[cg]then return end
cd[cg]=true
safeNotify("got "..cg,2)
end)
end
_startBackpackWatch()
LocalPlayer.CharacterAdded:Connect(function()
cd={}
_startBackpackWatch()
end)

local ce
local function _startAutoGunLoop()
if ce then return end
ce=task.spawn(function()
while _G.autogetguns_enabled do
local cf=_G.autogetguns_selected or{}
for cg,ch in ipairs(cf)do
if not _G.autogetguns_enabled then break end
_invokeGetGun(ch)
task.wait(_G.autogetguns_delay or 0.05)
end
task.wait(0)
end
ce=nil
end)
end

