_G.ks_enabled=false
_G.ks_volume=0.9
_G.ks_pitch=1.0
_G._ks_streak=0
_G._ks_lastKey=nil
_G._ks_lastAt=0
_G._ks_assetIds={}
_G._ks_cfg=nil
_G._ks_folder=nil

local function _ksLoad()
if _G._ks_cfg then return end
task.spawn(function()
local cf="QuakeSounds"
local cg="QuakeSounds/announcer_config.lua"
if not isfolder(cf)then pcall(makefolder,cf)end
local ch
pcall(function()
local ci=request{Url="https://raw.githubusercontent.com/localscripts/Audio/main/announcer_config.lua",Method="GET"}
if ci and ci.StatusCode==200 then writefile(cg,ci.Body);ch=ci.Body end
end)
if not ch and isfile(cg)then ch=readfile(cg)end
if not ch then return end
local ci,cj=pcall(function()return loadstring(ch)()end)
if not ci or type(cj)~="table"then return end
_G._ks_cfg=cj
_G._ks_folder=cj.folder
if _G._ks_folder and not isfolder(_G._ks_folder)then pcall(makefolder,_G._ks_folder)end
end)
end

local function _ksGetAsset(cf)
if _G._ks_assetIds[cf]then return _G._ks_assetIds[cf]end
local cg=_G._ks_cfg
if not cg then return nil end
local ch=cg.Sounds and cg.Sounds[cf]
if not ch then return nil end
local ci=_G._ks_folder or"QuakeSounds"
local cj=ci.."/"..ch
if not isfile(cj)then
local ck=cg.baseUrl..ch
local cl,cm=pcall(function()
return request{Url=ck,Method="GET"}
end)
if not cl or not cm or cm.StatusCode~=200 then return nil end
writefile(cj,cm.Body)
end
local ck,cl=pcall(getcustomasset,cj)
if ck and cl then _G._ks_assetIds[cf]=cl end
return _G._ks_assetIds[cf]
end

local function _ksPlay(cf)
if not cf then return end
local cg=tick()
if _G._ks_lastKey==cf and(cg-_G._ks_lastAt)<0.3 then return end
_G._ks_lastKey=cf;_G._ks_lastAt=cg
task.spawn(function()
local ch=_ksGetAsset(cf)
if not ch then return end
local ci=Instance.new"Sound"
ci.SoundId=ch
ci.Volume=_G.ks_volume or 0.9
ci.PlaybackSpeed=_G.ks_pitch or 1.0
ci.Parent=workspace
ci:Play()
ci.Ended:Connect(function()ci:Destroy()end)
end)
end

local function _ksResolve(cf)
if not _G._ks_cfg then return nil end
local cg=_G._ks_cfg.FragMap
local ch=_G._ks_cfg.SpecialMap
local ci=_G._ks_cfg.Sounds
local function has(cj)return cj and ci and ci[cj]~=nil end

if cf==1 then
for cj,ck in ipairs{"excellent","impressive","ownage","bullseye","eagleeye"}do
if has(ck)then return ck end
end
return nil
end
if cf==2 then
if ch and ch.DoubleKill then
for cj,ck in ipairs(ch.DoubleKill)do if has(ck)then return ck end end
end
if cg and has(cg[2])then return cg[2]end
return nil
end
local cj=0
if cg then
for ck,cl in pairs(cg)do
if type(ck)=="number"and has(cl)and ck>cj then cj=ck end
end
end
if cj>0 and cf>=cj then
local ck=cg[cj]
if has(ck)then
local cl=ck
_G._ks_streak=0
return cl
end
end
if cg and has(cg[cf])then return cg[cf]end
return nil
end

_G._ks_handleKill=function()
if not _G.ks_enabled then return end
_G._ks_streak=(_G._ks_streak or 0)+1
local cf=_ksResolve(_G._ks_streak)
_ksPlay(cf)
end

LocalPlayer.CharacterAdded:Connect(function(cf)
local cg=cf:WaitForChild("Humanoid",5)
if cg then cg.Died:Connect(function()_G._ks_streak=0;_G._ks_lastKey=nil end)end
end)
if LocalPlayer.Character then
local cf=LocalPlayer.Character:FindFirstChildOfClass"Humanoid"
if cf then cf.Died:Connect(function()_G._ks_streak=0;_G._ks_lastKey=nil end)end
end


task.spawn(function()
local cf=game:GetService"ReplicatedStorage"
local cg=cf:FindFirstChild"Killfeed"
if not cg then

local ch=tick()
while not cg and(tick()-ch)<10 do
cg=cf:FindFirstChild"Killfeed"
task.wait(0.5)
end
end
if not cg then return end

local ch={}
local function _kfIsDupe(ci)
local cj=os.clock()
for ck=#ch,1,-1 do
if cj-ch[ck].t>0.7 then table.remove(ch,ck)end
end
for ck,cl in ipairs(ch)do
if cl.msg==ci then return true end
end
table.insert(ch,{msg=ci,t=os.clock()})
return false
end

local function _kfIsMyKill(ci)
if not ci or ci==""then return false end
local cj=string.lower(ci)
local ck=cj:match"^(.-)%s+killed%s+"
if not ck then return false end
local cl=string.lower(LocalPlayer.Name)
local cm=string.lower(LocalPlayer.DisplayName or LocalPlayer.Name)
return ck:find("(@"..cl..")",1,true)
or ck:find(cl,1,true)
or ck:find(cm,1,true)
end

local function _kfIsMyDeath(ci)
if not ci or ci==""then return false end
local cj=string.lower(ci)
local ck=cj:match"%s+killed%s+(.-)$"
if not ck then return false end
local cl=string.lower(LocalPlayer.Name)
local cm=string.lower(LocalPlayer.DisplayName or LocalPlayer.Name)
return ck:find("(@"..cl..")",1,true)
or ck:find(cl,1,true)
or ck:find(cm,1,true)
end

cg.ChildAdded:Connect(function(ci)
if not _G.ks_enabled then return end
local cj=ci:IsA"StringValue"and ci.Value or ci.Name or""
if _kfIsDupe(cj)then return end
if _kfIsMyDeath(cj)then
_G._ks_streak=0;_G._ks_lastKey=nil;return
end
if _kfIsMyKill(cj)then
_G._ks_handleKill()
end
end)
end)

