Callback=function(cf)_G.ks_pitch=cf end
})






do
local cf=false
local cg=Enum.KeyCode.Q
local ch

local ci=false
local cj="on_shot"
local ck=Enum.KeyCode.F
local cl=Color3.fromRGB(0,200,255)
local cm=0.6
local cn=1.5
local co=0.3



local cp=game:GetService"UserInputService"
local cq=game:GetService"RunService"
local cr=game:GetService"TweenService"
game:GetService"Debris"

local function _fp_removeMarker(cs)
if not ch then return end
local ct=ch
ch=nil
ci=false
if cs then
ct:Destroy()
else

local cu=cr:Create(ct,TweenInfo.new(co,Enum.EasingStyle.Back,Enum.EasingDirection.In),{
Size=Vector3.zero
})
cu:Play()
cu.Completed:Connect(function()ct:Destroy()end)
end
end

local function _fp_createMarker(cs)
_fp_removeMarker(true)

local ct=Instance.new"Part"
ct.Name="FastPeekMarker"
ct.Anchored=true
ct.CanCollide=false
ct.CanQuery=false
ct.CanTouch=false
ct.Material=Enum.Material.Neon
ct.Shape=Enum.PartType.Cylinder
ct.Color=cl
ct.Transparency=0
ct.CastShadow=false
ct.Size=Vector3.new(0.08,0.5,0.5)

ct.CFrame=CFrame.new(cs)*CFrame.Angles(0,0,math.rad(90))
ct.Parent=workspace


local cu=Instance.new"Highlight"
cu.Name="FastPeekHL"
cu.Adornee=ct
cu.FillColor=_fp_fill_color or cl
cu.FillTransparency=cm or 0.6
cu.OutlineColor=_fp_outline_color or cl
cu.OutlineTransparency=_fp_outline_trans or 0
cu.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
cu.Parent=workspace


if _fp_anim_type=="blink"then
task.spawn(function()
while ch==ct and ct.Parent do
cu.FillTransparency=cm or 0.6
task.wait(0.3)
if ch~=ct then break end
cu.FillTransparency=1
task.wait(0.3)
end
end)
elseif _fp_anim_type=="fade_in"then
task.spawn(function()
local cv=0
cu.FillTransparency=1
while cv<0.5 and ch==ct do
cv=cv+task.wait()
cu.FillTransparency=1-(cv/0.5)*(1-(cm or 0.6))
end
end)
elseif _fp_anim_type=="pulse"then
task.spawn(function()
local cv=0
while ch==ct and ct.Parent do
cv=cv+task.wait()
cu.FillTransparency=(cm or 0.6)+0.3*math.abs(math.sin(cv*4))
end
end)
end


local cv=Vector3.new(0.08,cn*2,cn*2)
local cw=cr:Create(ct,TweenInfo.new(co,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{
Size=cv
})
cw:Play()

ch=ct
ci=true
end

local function _fp_teleportToMarker()
if not ch then return end
local cs=LocalPlayer.Character
local ct=cs and cs:FindFirstChild"HumanoidRootPart"
if not ct then return end
local cu=ch.Position
ct.CFrame=CFrame.new(cu)*(ct.CFrame-ct.CFrame.Position)
_fp_removeMarker(false)
end

local function _fp_raycastFloor()
local cs=LocalPlayer.Character
local ct=cs and cs:FindFirstChild"HumanoidRootPart"
if not ct then return nil end
local cu=RaycastParams.new()
cu.FilterType=Enum.RaycastFilterType.Exclude
cu.FilterDescendantsInstances={cs}
local cv=workspace:Raycast(ct.Position,Vector3.new(0,-50,0),cu)
if cv then return cv.Position end
return ct.Position-Vector3.new(0,3,0)
end


cp.InputBegan:Connect(function(cs,ct)
if ct then return end
if not cf then return end
local cu=cg
pcall(function()
if Options and Options.FastPeekKey and Options.FastPeekKey.Value then
local cv=Enum.KeyCode[tostring(Options.FastPeekKey.Value)]
if cv then cu=cv end
end
end)
if cs.KeyCode==cu then
local cv=_fp_raycastFloor()
if cv then _fp_createMarker(cv)end
end
local cv=ck
pcall(function()
if Options and Options.FastPeekManualKey and Options.FastPeekManualKey.Value then
local cw=Enum.KeyCode[tostring(Options.FastPeekManualKey.Value)]
if cw then cv=cw end
end
end)
if cs.KeyCode==cv and cj=="manual"then
_fp_teleportToMarker()
end
end)


_G._fp_onShot=function()
if cf and ci and cj=="on_shot"then
_fp_teleportToMarker()
end
end


_G._fp_onKill=function()
if cf and ci and cj=="on_kill"then
_fp_teleportToMarker()
end
end


cq.RenderStepped:Connect(function()
if not(cf and ci and cj=="on_visible")then return end
if not ch then return end
local cs=workspace.CurrentCamera
if not cs then return end local
ct, cu=cs:WorldToViewportPoint(ch.Position)
if cu then _fp_teleportToMarker()end
end)


