local function _loadCustomFontDmg(ch)
if _G._dmg_customFonts[ch]then return _G._dmg_customFonts[ch]end
local ci=_G._dmg_fontUrls[ch]
if not ci then return nil end
if not(getcustomasset and writefile)then return nil end
local cj="f3kel_fonts"
if isfolder and not isfolder(cj)then pcall(makefolder,cj)end
local ck=cj.."/"..ch..".ttf"
local cl=cj.."/"..ch..".font"
if not isfile(ck)then
local cm,cn=pcall(game.HttpGet,game,ci)
if cm and cn and#cn>100 then writefile(ck,cn)
else safeNotify("font download failed: "..ch,3);return nil end
end

if isfile(ck)then
local cm=getcustomasset(ck)
local cn='{"name":"'..ch..'","faces":[{"name":"Regular","weight":400,"style":"normal","assetId":"'..cm..'"}]}'
pcall(writefile,cl,cn)
end
if isfile(cl)then
local cm=getcustomasset(cl)
local cn,co=pcall(Font.new,cm)
if cn and co then
_G._dmg_customFonts[ch]=co
safeNotify("font loaded: "..ch,2)
return co
end

local cp,cq=pcall(function()
return Font.new(cm,Enum.FontWeight.Regular,Enum.FontStyle.Normal)
end)
if cp and cq then
_G._dmg_customFonts[ch]=cq
safeNotify("font loaded (fb): "..ch,2)
return cq
end
end
safeNotify("font load failed: "..ch,3)
return nil
end

