function animateNotification(ck,cl,cm)
local cn=getgenv().notificationAnimation or"slide"

if cn=="bounce"then
ck.Position=UDim2.new(1,0,0,20)

local co=game:GetService"TweenService":Create(
ck,
TweenInfo.new(0.5,Enum.EasingStyle.Bounce,Enum.EasingDirection.Out),
{Position=UDim2.new(1,-320,0,20)}
)

co:Play()

elseif cn=="zoom"then
ck.Size=UDim2.new(0,0,0,0)
ck.Position=UDim2.new(1,-160,0,60)

local co=game:GetService"TweenService":Create(
ck,
TweenInfo.new(0.3,Enum.EasingStyle.Back,Enum.EasingDirection.Out),
{
Size=UDim2.new(0,300,0,80),
Position=UDim2.new(1,-320,0,20)
}
)

co:Play()

elseif cn=="shake"then
ck.Position=UDim2.new(1,-320,0,20)

task.spawn(function()
for co=1,5 do
ck.Position=UDim2.new(
1,-320
+math.random(-5,5),
0,
20+math.random(-3,3)
)
task.wait(0.05)
end

ck.Position=UDim2.new(1,-320,0,20)
end)

elseif cn=="typewriter"then
ck.Position=UDim2.new(1,-320,0,20)
cm.Text=""

task.spawn(function()
for co=1,#cl do
cm.Text=cl:sub(1,co)
task.wait(0.03)
end
end)

else

ck.Position=UDim2.new(1,0,0,20)

local co=game:GetService"TweenService":Create(
ck,
TweenInfo.new(0.4,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),
{Position=UDim2.new(1,-320,0,20)}
)

co:Play()
end
end

