function onHit(cl,cm,cn,co,cp)
if not cl then return end

if ck.systems.hitNotifications and showHitMessage then
showHitMessage(cl,cp,co,cm,cn)
end

if ck.systems.damageIndicator and spawnDamageIndicator then
spawnDamageIndicator(cl.Character,cm)
end
if cfg.hiteffect_stars and _G._starsEmit then
local cq=cl.Character and cl.Character:FindFirstChild"HumanoidRootPart"
if cq then task.spawn(_G._starsEmit,cq.CFrame,cfg.stars_amount or 10)end
end

if ck.systems.hitmarker and showHitmarker then
showHitmarker()
end
end

function onKill(cl,cm,cn)
if not cl then return end

if ck.systems.killNotifications and showKillMessage then
showKillMessage(cl,cn,cm)
end

if _G.ks_enabled and _G._ks_handleKill then
_G._ks_handleKill()
end
end

