function setupViewmodel(cm)
local cn=cm:WaitForChild"Head"
local co=cm:WaitForChild"Torso"or cm:WaitForChild"UpperTorso"
local cp=cm:WaitForChild"Humanoid"
local cq=cm:FindFirstChild"Right Arm"or cm:FindFirstChild"RightUpperArm"
local cr=cm:FindFirstChild"Left Arm"or cm:FindFirstChild"LeftUpperArm"

local cs=co:FindFirstChild"Right Shoulder"
local ct=co:FindFirstChild"Left Shoulder"

local function hasTool()
return cm:FindFirstChildOfClass"Tool"~=nil
end

RunService.RenderStepped:Connect(function(cu)
if not cm.Parent then return end

local cv=workspace.CurrentCamera
local cw=(cv.CFrame.Position-cn.Position).Magnitude
local cx=cw<0.8

if getgenv().viewmodel.alwaysViewmodel then

co.LocalTransparencyModifier=1
cn.LocalTransparencyModifier=1
local cy=cn:FindFirstChildOfClass"Decal"
if cy then cy.Transparency=1 end

for cz,cA in pairs(cm:GetChildren())do
if cA:IsA"BasePart"and(cA.Name:lower():find"leg"or cA.Name:lower():find"foot")then
cA.LocalTransparencyModifier=1
end
end

if cq then cq.LocalTransparencyModifier=0 end
if cr then cr.LocalTransparencyModifier=0 end

cx=true
else

if cx then
cn.LocalTransparencyModifier=1
local cy=cn:FindFirstChildOfClass"Decal"
if cy then cy.Transparency=1 end
if cq then cq.LocalTransparencyModifier=0 end
if cr then cr.LocalTransparencyModifier=0 end
else
cn.LocalTransparencyModifier=0
local cy=cn:FindFirstChildOfClass"Decal"
if cy then cy.Transparency=0 end
end
end

local cy=cx and(hasTool()or getgenv().viewmodel.alwaysViewmodel)

if cy and getgenv().viewmodel.enabled then

local cz=cm:FindFirstChildOfClass"Tool"
if cz then
for cA,cB in pairs(cz:GetDescendants())do
if cB:IsA"BasePart"then

cB.Transparency=getgenv().viewmodel.transparency

if not getgenv().viewmodel.textures then
for cC,cD in pairs(cB:GetChildren())do
if cD:IsA"Texture"or cD:IsA"Decal"then
cD.Transparency=1
end
end
end

cB.Material=Enum.Material[getgenv().viewmodel.material]
end
end

if cq then
cq.Transparency=getgenv().viewmodel.transparency
cq.Material=Enum.Material[getgenv().viewmodel.material]
end
if cr then
cr.Transparency=getgenv().viewmodel.transparency
cr.Material=Enum.Material[getgenv().viewmodel.material]
end

if getgenv().viewmodel.chams then
if not cl then
cl=Instance.new"Highlight"
cl.FillColor=getgenv().viewmodel.chamsColor
cl.FillTransparency=getgenv().viewmodel.chamsTransparency
cl.OutlineTransparency=1
cl.Parent=cz
else
cl.FillColor=getgenv().viewmodel.chamsColor
cl.FillTransparency=getgenv().viewmodel.chamsTransparency
end
elseif cl then
cl:Destroy()
cl=nil
end
end

if cs and ct then
local cA=co.CFrame:ToObjectSpace(cv.CFrame)
local cB=cA.LookVector
local cC=math.asin(-cB.Y)
local cD=math.atan2(cB.X,-cB.Z)

cC=math.clamp(cC,math.rad(-60),math.rad(60))
cD=math.clamp(cD,math.rad(-80),math.rad(80))

local cE=CFrame.new()
local cF=CFrame.new()

local cG=co.AssemblyLinearVelocity
local cH=Vector3.new(cG.X,0,cG.Z).Magnitude
local cI=math.clamp(cH/cp.WalkSpeed,0,1)
local cJ=tick()
local cK=10+(cI*8)
local cL=0.18*cI
local cM=math.cos(cJ*cK)*cL
local cN=math.abs(math.sin(cJ*cK))*cL

cE=CFrame.new(cM,-cN,0)
cF=CFrame.new(-cM,-cN,0)

local cO=cE*CFrame.Angles(-cC*0.8-math.rad(15),cD*0.7,0)
local cP=cF*CFrame.Angles(-cC*0.8-math.rad(15),cD*0.7,0)

local cQ=1-math.exp(-10*cu)
cs.Transform=cs.Transform:Lerp(cO,cQ)
ct.Transform=ct.Transform:Lerp(cP,cQ)
end
else
if cs and ct then
local cz=1-math.exp(-12*cu)
cs.Transform=cs.Transform:Lerp(CFrame.new(),cz)
ct.Transform=ct.Transform:Lerp(CFrame.new(),cz)
end
end
end)
end

game.Players.LocalPlayer.CharacterAdded:Connect(setupViewmodel)
if game.Players.LocalPlayer.Character then
setupViewmodel(game.Players.LocalPlayer.Character)
end

