function inBox(cn,co,cp)
return math.abs(cn-cp.cx)<=cp.hx and math.abs(co-cp.cz)<=cp.hz
end

function isInSubRegion(cn,co)
for cp,cq in ipairs(cm)do
if inBox(cn,co,cq)then return true end
end
return false
end

function setupSpeedBypass(cn)
local co=cn:WaitForChild"Humanoid"
local cp=cn:WaitForChild"HumanoidRootPart"
local cq=cn:WaitForChild"Head"

