local cs=co:GetPropertyChangedSignal"Jump"
task.wait(1)

for ct,cu in getconnections(cs)do
cu:Disable()
end

end)

task.spawn(function()
for cs,ct in getconnections(cq:GetPropertyChangedSignal"CanCollide")do
