while cn and cn.Parent and co.Health>0 do
task.wait()

if _G.cs2bhop_enabled then

if getgenv().speedBypass.enabled then
co.JumpHeight=getgenv().speedBypass.jumpPower
end
elseif not getgenv().speedBypass.enabled then
co.JumpHeight=cr
else
local cs,ct=cp.Position.X,cp.Position.Z
if getgenv().speedBypass.useRegions then
if isInSubRegion(cs,ct)then
co.WalkSpeed=32
co.JumpHeight=cr
elseif inBox(cs,ct,prison)then
co.WalkSpeed=50
co.JumpHeight=25
else
co.WalkSpeed=getgenv().speedBypass.speed
co.JumpHeight=getgenv().speedBypass.jumpPower
end
else
co.WalkSpeed=getgenv().speedBypass.speed
co.JumpHeight=getgenv().speedBypass.jumpPower
end
end
end
end)
end

game.Players.LocalPlayer.CharacterAdded:Connect(setupSpeedBypass)
if game.Players.LocalPlayer.Character then
setupSpeedBypass(game.Players.LocalPlayer.Character)
