function updateRageFovOrigin()
if not fovCircle then return end

local cn=workspace.CurrentCamera.ViewportSize
local co=cn.X/2
local cp=cn.Y/2

if getgenv().rageFovOrigin=="tool"then
local cq=game.Players.LocalPlayer.Character
local cr=currentTarget and currentTarget.Character and currentTarget.Character:FindFirstChild"HumanoidRootPart"

if not cr then
if cq then
local cs=cq:FindFirstChildOfClass"Tool"
if cs and cs:FindFirstChild"Handle"then
local ct,cu=workspace.CurrentCamera:WorldToViewportPoint(cs.Handle.Position)
if cu then
fovCircle.Position=Vector2.new(ct.X,ct.Y)
if rageFovLabel then
rageFovLabel.Position=UDim2.new(0,ct.X,0,ct.Y)
end
return
end
end
end
end
end

fovCircle.Position=Vector2.new(co,cp)
end

ck.playAnim=playAnim

do
local cn=game:GetService"Players"
local co=game:GetService"RunService"
local cp=game:GetService"GuiService"
local cq=cn.LocalPlayer

local cr=Instance.new"ScreenGui"
cr.Name="reversal_esp"
cr.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
cr.ResetOnSpawn=false
if gethui then cr.Parent=gethui()
elseif syn and syn.protect_gui then syn.protect_gui(cr);cr.Parent=game:GetService"CoreGui"
else cr.Parent=game:GetService"CoreGui"end

local cs={}

local function getTeamColor(ct)
if cfg.espuseteamcolors then
if ct.Team then return ct.Team.TeamColor.Color end
return cfg.espcolor or Color3.fromRGB(255,255,255)
end

local cu=ct.Team and ct.Team.Name or""
if cu:lower():find"guard"then return cfg.espguards or Color3.fromRGB(0,170,255)
elseif cu:lower():find"inmate"or cu:lower():find"prisoner"then return cfg.espinmates or Color3.fromRGB(255,150,50)
elseif cu:lower():find"crimin"then return cfg.espcriminals or Color3.fromRGB(255,60,60)
end
return cfg.espcolor or Color3.fromRGB(255,255,255)
end

local function shouldShow(ct)
if not cfg.esp then return false end
if ct==cq then return false end
if not ct.Character or not ct.Character:FindFirstChild"HumanoidRootPart"then return false end
if cfg.espteamcheck and not cfg.espshowteam and ct.Team==cq.Team and ct.Team~=nil then return false end

local cu=cq.Character and cq.Character:FindFirstChild"HumanoidRootPart"

if cu and cfg.espmaxdist then
local cv=(ct.Character.HumanoidRootPart.Position-cu.Position).Magnitude


if not cfg.esp_inf_dist and cv>cfg.espmaxdist then
return false
end
end

return true
end

local function makeLabel(ct,cu,cv,cw,cx)
local cy=Instance.new"Frame"
cy.Name=cu.."_f"
cy.BorderSizePixel=0
cy.BackgroundTransparency=1
cy.Size=UDim2.new(0,160,0,16)
cy.Parent=ct

local cz=Instance.new"TextLabel"
cz.Name=cu.."_t"
cz.BorderSizePixel=0
cz.TextSize=cfg.esptextsize or 13
cz.BackgroundTransparency=1
cz.FontFace=Font.new([[rbxasset://fonts/families/Inconsolata.json]],Enum.FontWeight.Regular,Enum.FontStyle.Normal)
cz.TextColor3=cw
cz.Size=UDim2.new(1,0,1,0)
cz.Text=cv
cz.TextXAlignment=Enum.TextXAlignment.Center
cz.Parent=cy

local cA=Instance.new"UIStroke"
cA.Thickness=cx
cA.Parent=cz

return cy,cz
end

local function buildESP(ct)
local cu=Instance.new"Folder"
cu.Name=ct.Name.."_esp"
cu.Parent=cr

local cv=getTeamColor(ct)

local cw=Instance.new"Frame"
cw.Name="esp_outlines_f"
cw.BorderSizePixel=0
cw.BackgroundTransparency=1
cw.Size=UDim2.new(0,60,0,100)
cw.Parent=cu



local cx=Instance.new"UIStroke"
cx.Name="esp_box_glow_stroke"
cx.Color=cfg.esp_box_glow_color or Color3.fromRGB(255,80,80)
cx.Thickness=6
cx.Transparency=0.5
cx.Enabled=cfg.esp_box_glow or false
cx.Parent=cw

local cy=Instance.new"UIStroke"
cy.Name="esp_outline_m"
cy.Color=cv
cy.Thickness=cfg.espboxthickness or 1
cy.Parent=cw

local cz=Instance.new"UIGradient"
cz.Name="esp_outline_ug_customizable"
cz.Enabled=cfg.esp2_box_outline_gradient or false
cz.Rotation=cfg.esp2_box_outline_grad_rot or-180
cz.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,cfg.espcolor or Color3.fromRGB(255,255,255)),
ColorSequenceKeypoint.new(1,cfg.esp2_box_fill_color2 or Color3.fromRGB(0,0,0)),
}
cz.Parent=cy

local cA=Instance.new"Frame"
cA.Name="extra_filled_box_f"
cA.ZIndex=-3
cA.BorderSizePixel=0
cA.BackgroundColor3=cfg.esp2_box_fill_color or Color3.fromRGB(255,255,255)
cA.Size=UDim2.new(0,60,0,100)
cA.BorderColor3=Color3.fromRGB(0,0,0)
cA.BackgroundTransparency=cfg.esp2_box_fill_trans or 0.6
cA.Visible=cfg.esp2_box_fill or false
cA.Parent=cu

local cB=Instance.new"UIGradient"
cB.Name="extra_box_gradient_ug"
cB.Enabled=cfg.esp2_box_fill_gradient or false
cB.Rotation=cfg.esp2_box_fill_grad_rot or 90
cB.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,cfg.esp2_box_fill_color or Color3.fromRGB(255,255,255)),
ColorSequenceKeypoint.new(1,cfg.esp2_box_fill_color2 or Color3.fromRGB(0,0,0)),
}
cB.Parent=cA

local cC=Instance.new"Frame"
cC.Name="esp_healthbar_outer_f"
cC.BorderSizePixel=0
cC.BackgroundColor3=Color3.fromRGB(0,0,0)
cC.Size=UDim2.new(0,6,0,100)
cC.Parent=cu

local cD=Instance.new"Frame"
cD.Name="esp_healthbar_bg_f"
cD.BorderSizePixel=0
cD.BackgroundColor3=Color3.fromRGB(30,30,30)
cD.Size=UDim2.new(0,4,1,-2)
cD.Position=UDim2.new(0,1,0,1)
cD.Parent=cC

local cE=Instance.new"Frame"
cE.Name="hb_indicator_f"
cE.ZIndex=2
cE.BorderSizePixel=0
cE.BackgroundColor3=cfg.esp2_hb_color_top or Color3.fromRGB(255,255,255)
cE.Size=UDim2.new(1,0,1,0)
cE.AnchorPoint=Vector2.new(0,1)
cE.Position=UDim2.new(0,0,1,0)
cE.Parent=cD

local cF=Instance.new"UIGradient"
cF.Name="hb_gradient_ug"
cF.Rotation=90
cF.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,Color3.fromRGB(255,255,255)),
ColorSequenceKeypoint.new(1,Color3.fromRGB(255,255,255)),
}
cF.Parent=cE

local cG,cH=makeLabel(cu,"esp_username",ct.DisplayName,Color3.fromRGB(255,255,255),0.66)
local cI,cJ=makeLabel(cu,"esp_tool","none",Color3.fromRGB(255,255,255),0.66)
local cK,cL=makeLabel(cu,"esp_team","",Color3.fromRGB(255,137,0),0.8)
local cM,cN=makeLabel(cu,"esp_htex","100/100",Color3.fromRGB(255,255,255),0.8)

return{
container=cu,
box=cw,
outlineMain=cy,
outlineGrad=cz,
boxGlowStroke=cx,
filledBox=cA,
filledGrad=cB,
hbOuter=cC,
hbBg=cD,
hbFill=cE,
hbGrad=cF,
userFrame=cG,userLabel=cH,
toolFrame=cI,toolLabel=cJ,
teamFrame=cK,teamLabel=cL,
htexFrame=cM,htexLabel=cN,
}
end

local function removeESP(ct)
if cs[ct]then
pcall(function()cs[ct].container:Destroy()end)
cs[ct]=nil
end
end

local function hideESP(ct)
ct.box.Visible=false
ct.filledBox.Visible=false
ct.hbOuter.Visible=false
ct.userFrame.Visible=false
ct.toolFrame.Visible=false
ct.teamFrame.Visible=false
ct.htexFrame.Visible=false
end

local function updateESP(ct,cu)
if not shouldShow(ct)then hideESP(cu)return end

local cv=ct.Character
local cw=cv and cv:FindFirstChild"HumanoidRootPart"
local cx=cv and cv:FindFirstChildWhichIsA"Humanoid"
if not cw or not cx then hideESP(cu)return end

local cy=workspace.CurrentCamera
local cz=cp:GetGuiInset().Y

local cA=cw.Position+Vector3.new(0,3.5,0)
local cB=cw.Position-Vector3.new(0,3.5,0)

local cC=cv:FindFirstChild"Head"
if cC then cA=cC.Position+Vector3.new(0,cC.Size.Y*0.5,0)end

local cD=cv:FindFirstChild"LowerTorso"
if cD then cB=cD.Position-Vector3.new(0,cD.Size.Y*0.5+0.1,0)end

local cE=cy:WorldToViewportPoint(cA)
local cF=cy:WorldToViewportPoint(cB)

if cE.Z<0 then hideESP(cu)return end

local cG=cF.Y-cE.Y



local cH=1.0
if cfg.esp_dynamic_boxes and dist>0 then
cH=math.clamp(50/math.max(dist,1),0.35,2.0)
end
local cI=cG*0.55*cH
local cJ=cE.X-cI*0.5
local cK=cE.Y-cz

local cL=cq.Character and cq.Character:FindFirstChild"HumanoidRootPart"
local cM=cL and(cw.Position-cL.Position).Magnitude or 0

local cN=getTeamColor(ct)
local cO=math.clamp(cfg.esptextsize or 13,8,20)
local cP=cfg.espboxthickness or 1

cu.box.Visible=cfg.espboxes~=false
cu.box.Position=UDim2.new(0,cJ,0,cK)
cu.box.Size=UDim2.new(0,cI,0,cG)
cu.outlineMain.Color=cfg.esp2_box_outline_color or cN

if cu.boxGlowStroke then
cu.boxGlowStroke.Enabled=cfg.esp_box_glow or false
cu.boxGlowStroke.Color=cfg.esp_box_glow_color or cN
cu.boxGlowStroke.Transparency=cfg.esp_box_glow_trans or 0.5
cu.boxGlowStroke.Thickness=6
end
cu.outlineMain.Thickness=cP
cu.outlineGrad.Enabled=cfg.esp2_box_outline_gradient or false
cu.outlineGrad.Rotation=cfg.esp2_box_outline_grad_rot or 180

if cfg.esp2_box_outline_grad_spin then
local cQ=((cfg.esp2_box_outline_grad_spin_speed or 60)*(1.6666666666666665E-2))%360
cfg.esp2_box_outline_grad_rot=((cfg.esp2_box_outline_grad_rot or 0)+cQ)%360
end
cu.outlineGrad.Rotation=cfg.esp2_box_outline_grad_rot or 180
if cfg.esp2_box_outline_grad3 and cfg.esp2_box_outline_color3 then
cu.outlineGrad.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,cfg.esp2_box_outline_color or cN),
ColorSequenceKeypoint.new(0.5,cfg.esp2_box_outline_color2 or Color3.fromRGB(0,0,0)),
ColorSequenceKeypoint.new(1,cfg.esp2_box_outline_color3 or Color3.fromRGB(0,255,200)),
}
else
cu.outlineGrad.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,cfg.esp2_box_outline_color or cN),
ColorSequenceKeypoint.new(1,cfg.esp2_box_outline_color2 or Color3.fromRGB(0,0,0)),
}
end

cu.filledBox.Visible=cfg.esp2_box_fill or false
cu.filledBox.Position=UDim2.new(0,cJ,0,cK)
cu.filledBox.Size=UDim2.new(0,cI,0,cG)
cu.filledBox.BackgroundColor3=cfg.esp2_box_fill_color or Color3.fromRGB(255,255,255)
cu.filledBox.BackgroundTransparency=cfg.esp2_box_fill_trans or 0.6
cu.filledGrad.Enabled=cfg.esp2_box_fill_gradient or false
cu.filledGrad.Rotation=cfg.esp2_box_fill_grad_rot or 90

if cfg.esp2_box_fill_grad_spin then
local cQ=((cfg.esp2_box_fill_grad_spin_speed or 60)*(1.6666666666666665E-2))%360
cfg.esp2_box_fill_grad_rot=((cfg.esp2_box_fill_grad_rot or 90)+cQ)%360
end
cu.filledGrad.Rotation=cfg.esp2_box_fill_grad_rot or 90
if cfg.esp2_box_fill_grad3 and cfg.esp2_box_fill_color3 then
cu.filledGrad.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,cfg.esp2_box_fill_color or Color3.fromRGB(255,255,255)),
ColorSequenceKeypoint.new(0.5,cfg.esp2_box_fill_color2 or Color3.fromRGB(0,0,0)),
ColorSequenceKeypoint.new(1,cfg.esp2_box_fill_color3 or Color3.fromRGB(255,100,0)),
}
else
cu.filledGrad.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,cfg.esp2_box_fill_color or Color3.fromRGB(255,255,255)),
ColorSequenceKeypoint.new(1,cfg.esp2_box_fill_color2 or Color3.fromRGB(0,0,0)),
}
end

local cQ=cfg.esp2_healthbar_width or 4
cu.hbOuter.Visible=cfg.esphealthbar~=false
cu.hbOuter.Position=UDim2.new(0,cJ-cQ-4,0,cK)
cu.hbOuter.Size=UDim2.new(0,cQ+2,0,cG)

local cR=math.clamp(cx.Health/math.max(cx.MaxHealth,1),0,1)
cu.hbFill.Size=UDim2.new(1,0,cR,0)

if cfg.esp2_hb_multicolor then
cu.hbGrad.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,cfg.esp2_hb_color_top),
ColorSequenceKeypoint.new(0.33,cfg.esp2_hb_color3),
ColorSequenceKeypoint.new(0.66,cfg.esp2_hb_color4),
ColorSequenceKeypoint.new(1,cfg.esp2_hb_color_bot),
}
else
cu.hbGrad.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,cfg.esp2_hb_color_top),
ColorSequenceKeypoint.new(1,cfg.esp2_hb_color_bot),
}
end

cu.userFrame.Visible=true
cu.userFrame.Position=UDim2.new(0,cJ,0,cK-16)
cu.userFrame.Size=UDim2.new(0,cI,0,16)
cu.userLabel.TextSize=cO
cu.userLabel.Text=ct.DisplayName.." (@"..ct.Name..")"

if cfg.esp_username_grad then
if not cu.userLabel:FindFirstChildOfClass"UIGradient"then
Instance.new("UIGradient",cu.userLabel)
end
local cS=cu.userLabel:FindFirstChildOfClass"UIGradient"
if cS then
cS.Enabled=true
if cfg.esp_username_grad_spin then
local cT=((cfg.esp_username_grad_spin_speed or 60)*(1.6666666666666665E-2))%360
cS.Rotation=(cS.Rotation+cT)%360
end
cS.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,cfg.esp_username_color1 or cN),
ColorSequenceKeypoint.new(0.5,cfg.esp_username_color2 or cN),
ColorSequenceKeypoint.new(1,cfg.esp_username_color3 or cN),
}
end
else
local cS=cu.userLabel:FindFirstChildOfClass"UIGradient"
if cS then cS.Enabled=false end
cu.userLabel.TextColor3=cN
end

local cS=cv:FindFirstChildWhichIsA"Tool"
cu.toolFrame.Visible=cfg.espboxes~=false
cu.toolFrame.Position=UDim2.new(0,cJ,0,cK+cG+2)
cu.toolFrame.Size=UDim2.new(0,cI,0,16)
cu.toolLabel.TextSize=cO
cu.toolLabel.Text=cS and cS.Name or"none"

if cfg.esp_tool_grad then
if not cu.toolLabel:FindFirstChildOfClass"UIGradient"then
Instance.new("UIGradient",cu.toolLabel)
end
local cT=cu.toolLabel:FindFirstChildOfClass"UIGradient"
if cT then
cT.Enabled=true
if cfg.esp_tool_grad_spin then
local cU=((cfg.esp_tool_grad_spin_speed or 60)*(1.6666666666666665E-2))%360
cT.Rotation=(cT.Rotation+cU)%360
end
cT.Color=ColorSequence.new{
ColorSequenceKeypoint.new(0,cfg.esp_tool_color1 or Color3.fromRGB(255,255,255)),
ColorSequenceKeypoint.new(0.5,cfg.esp_tool_color2 or Color3.fromRGB(255,200,0)),
ColorSequenceKeypoint.new(1,cfg.esp_tool_color3 or Color3.fromRGB(255,100,0)),
}
end
else
local cT=cu.toolLabel:FindFirstChildOfClass"UIGradient"
if cT then cT.Enabled=false end
cu.toolLabel.TextColor3=Color3.fromRGB(255,255,255)
end

local cT=Color3.fromRGB(255,137,0)
local cU=""
if ct.Team then
cU=ct.Team.Name
cT=ct.Team.TeamColor.Color
end
cu.teamFrame.Visible=cfg.espshowteam~=false and cU~=""
cu.teamFrame.Position=UDim2.new(0,cJ,0,cK+cG+18)
cu.teamFrame.Size=UDim2.new(0,cI,0,16)
cu.teamLabel.TextSize=cO
cu.teamLabel.Text=cU
cu.teamLabel.TextColor3=cT

local cV=math.floor(cx.MaxHealth)
local cW=math.floor(cx.Health)
local cX=(cfg.espshowteam and cU~="")and 34 or 18
cu.htexFrame.Visible=cfg.esphealthtext~=false
cu.htexFrame.Position=UDim2.new(0,cJ,0,cK+cG+cX)
cu.htexFrame.Size=UDim2.new(0,cI,0,16)
cu.htexLabel.TextSize=cO
cu.htexLabel.Text=cW.."/"..cV
cu.htexLabel.TextColor3=Color3.fromRGB(255,255,255)

if cfg.espshowdist then
cu.htexLabel.Text=cW.."/"..cV.." ["..math.floor(cM).."m]"
end
end

local function initPlayer(ct)
if ct==cq then return end
cs[ct]=buildESP(ct)
ct.CharacterAdded:Connect(function()
task.wait(0.2)
end)
end

for ct,cu in ipairs(cn:GetPlayers())do
task.spawn(initPlayer,cu)
end

cn.PlayerAdded:Connect(function(ct)
task.wait(0.5)
initPlayer(ct)
end)

cn.PlayerRemoving:Connect(function(ct)
removeESP(ct)
end)

local ct=0
co.RenderStepped:Connect(function(cu)
ct=ct+cu
local cv=1/math.clamp(cfg.espFps or 60,1,300)
if ct<cv then return end
ct=0
for cw,cx in pairs(cs)do
if cw and cw.Parent then
pcall(updateESP,cw,cx)
else
pcall(function()cx.container:Destroy()end)
cs[cw]=nil
end
end
end)





local cu=co.Heartbeat:Connect(function()
if not cfg.instantStop then return end

local cu=cq.Character
if not cu then return end

local cv=cu:FindFirstChildOfClass"Humanoid"
local cw=cu:FindFirstChild"HumanoidRootPart"

if not cv or not cw then return end

if cv.MoveDirection.Magnitude<0.01 then
local cx=cw.AssemblyLinearVelocity

cw.AssemblyLinearVelocity=Vector3.new(
0,
cx.Y,
0
)

cw.AssemblyAngularVelocity=Vector3.zero
end
end)

_G.reversalConnections=_G.reversalConnections or{}
table.insert(_G.reversalConnections,cu)



local cv={pos=nil,look=nil}
local cw=false
local cx

pcall(function()co:UnbindFromRenderStep"reversal_camDelay"end)




co:BindToRenderStep("reversal_camDelay",Enum.RenderPriority.Last.Value,function()
local cy=workspace.CurrentCamera
if not cy then return end

if not cfg.camDelay then

if cx then
pcall(function()cy.CameraType=cx end)
cx=nil
end
cv.pos=nil
cv.look=nil
cw=false
return
end

if cw then return end
cw=true


if cy.CameraType~=Enum.CameraType.Custom or not cx then
if not cx then cx=cy.CameraType end
pcall(function()cy.CameraType=Enum.CameraType.Custom end)
end

local cz=cy.CFrame

if not cv.pos then
cv.pos=cz.Position
cv.look=cz.LookVector
end

cv.pos=cv.pos:Lerp(cz.Position,math.clamp(cfg.camDelayPosition or 0.14,0.01,0.99))
cv.look=(cv.look:Lerp(cz.LookVector,math.clamp(cfg.camDelayRotation or 0.6,0.01,0.99))).Unit
if cv.look.Magnitude>0 then
cy.CFrame=CFrame.lookAt(cv.pos,cv.pos+cv.look)
end

cw=false
end)


function createGhostEffect(cy,cz)
cz=cz or{}
local cA=cz.size or 1
local cB=cz.outlineColor or Color3.fromRGB(255,255,255)
local cC=cz.fillColor or Color3.fromRGB(255,255,255)
local cD=cz.modelColor or Color3.fromRGB(200,200,200)

local cE=cz.animDuration or 1

if not cy then return end

local cF=game:GetService"TweenService"
local cG=Instance.new"Model"
cG.Name="ghost_effect"
cG.Parent=workspace

for cH,cI in ipairs(cy:GetChildren())do
if cI:IsA"BasePart"then
local cJ=Instance.new"Part"
cJ.Name=cI.Name
cJ.Size=cI.Size*cA
cJ.CFrame=cI.CFrame
cJ.Color=cD
cJ.Material=Enum.Material.SmoothPlastic
cJ.Transparency=0
cJ.Anchored=true
cJ.CanCollide=false
cJ.CanTouch=false
cJ.CanQuery=false
cJ.Parent=cG
end
end

Instance.new("Humanoid",cG)
local cH=Instance.new"Highlight"
cH.Adornee=cG
cH.FillColor=cC
cH.OutlineColor=cB
cH.FillTransparency=0
cH.OutlineTransparency=0
cH.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
cH.Parent=cG

for cI,cJ in ipairs(cG:GetChildren())do
if cJ:IsA"BasePart"then
cF:Create(cJ,TweenInfo.new(cE),{
CFrame=cJ.CFrame+Vector3.new(0,3,0),
Transparency=1
}):Play()
end
end

cF:Create(cH,TweenInfo.new(cE),{
FillTransparency=1,
OutlineTransparency=1
}):Play()

task.delay(cE,function()
if cG and cG.Parent then
cG:Destroy()
end
end)
end


end



end)
